insert into public.cards (key, season, set_id, division, name, category, rarity, glyph, motif, known_for, lore, fact, fact_source, fact_url, question, home_area,
                          geog, geo_kind, geo_confidence, geo_source, geo_note, radius_m, copies_total, numbered, front_path, back_path, thumb_path, art_credit,
                          status, signed_off)
select v.key, 1, s.id, v.division, v.name, v.category, v.rarity, v.glyph, v.motif, v.known_for, v.lore, v.fact, v.fact_source, v.fact_url, v.question, v.home_area,
       st_setsrid(st_makepoint(v.lng::double precision, v.lat::double precision), 4326)::geography, v.geo_kind, v.geo_confidence, v.geo_source, v.geo_note, v.radius_m::integer,
       v.copies_total::integer, v.numbered::boolean, v.front_path, v.back_path, v.thumb_path, v.art_credit,
       'live', true
from (values
('AGE-03', 'agege', 'Ikeja', 'Pen Cinema', 'culture', 'common', 'PEN', 'bridge', 'Names a bridge long after the last film rolled', 'Before Netflix, na Pen Cinema be Agege big screen.', 'Pen Cinema in Agege was one of the few Lagos cinema houses still running in the early 1990s. Its name lives on in the 1.4 km Pen Cinema Bridge, a flyover project started in 2017.', 'Is This the Age of Nollywood at Domestic Box Office? (Afrocritik)', 'https://afrocritik.com/is-this-the-age-of-nollywood-at-domestic-box-office/', 'What was the first film you ever watched in a cinema?', 'Agege', 3.320339, 6.622917, 'area', 'low', 'osm:node/501464088', 'place not found, centre of its area', 500, null, false, '/cards/s1/front/AGE-03.webp', '/cards/s1/back/AGE-03.webp', '/cards/s1/thumb/AGE-03.webp', null),
('AGE-ORI-01', 'orile-agege', 'Ikeja', 'Agege Proper', 'history', 'common', 'ORILE', 'town', 'Was Agege before Agege was Agege', 'Before Agege get station, Orile don dey here.', 'Orile-Agege is the original homestead of the Agege community, settled by Awori people. Orile means ''proper'', setting it apart from the newer town that grew around the railway station built between 1895 and 1911.', 'Agege (Wikipedia)', 'https://en.wikipedia.org/wiki/Agege', 'Which part of your area is the oldest, and how do you know?', 'Orile Agege', 3.315955, 6.631037, 'area', 'medium', 'osm:way/220745207', null, 500, null, false, '/cards/s1/front/AGE-ORI-01.webp', '/cards/s1/back/AGE-ORI-01.webp', '/cards/s1/thumb/AGE-ORI-01.webp', null),
('AGE-ORI-02', 'orile-agege', 'Ikeja', 'Orile Festivals', 'culture', 'common', 'GELEDE', 'mask', 'Keeps the old drums talking', 'Na Orile old drums still dey talk.', 'Orile-Agege is tied to older Yoruba religious traditions, with ancient deities and festivals that include Egungun and Gelede, local history says.', 'Agege (Wikipedia)', 'https://en.wikipedia.org/wiki/Agege', 'Which festival do you remember most from growing up?', 'Orile Agege', 3.315955, 6.631037, 'area', 'medium', 'osm:way/220745207', null, 500, null, false, '/cards/s1/front/AGE-ORI-02.webp', '/cards/s1/back/AGE-ORI-02.webp', '/cards/s1/thumb/AGE-ORI-02.webp', null),
('AJR-01', 'ajeromi-ifelodun', 'Badagry', 'Maracana Stadium', 'sport', 'rare', 'MARA', 'stadium', 'Turns street ballers into Super Eagles', 'Na for this ground Ajegunle legends learn to dribble the world.', 'Odion Ighalo, Samson Siasia, Obafemi Martins and Taribo West all played at Ajegunle''s Maracana ground. By 2023 an upgrade had turned the old dumpsite into a centre with 19 pitches and hostels with 192 beds.', 'Ambode to Give Ajegunle''s Maracana Stadium Status (ThisDay)', 'https://thisdaylive.com/index.php/2016/09/12/ambode-to-give-ajegunles-maracana-stadium-status', 'Which Ajegunle footballer would make your all-time Super Eagles team?', 'Ajeromi-Ifelodun', 3.33351, 6.448156, 'area', 'low', 'osm:node/13236892517', 'place not found, centre of its area', 500, 1000, false, '/cards/s1/front/AJR-01.webp', '/cards/s1/back/AJR-01.webp', '/cards/s1/thumb/AJR-01.webp', null),
('AJR-02', 'ajeromi-ifelodun', 'Badagry', 'AJ Music', 'music', 'common', 'AJ', 'drum', 'Gets the whole street dancing galala', 'Who never dance galala never reach AJ City.', 'AJ music, a blend of Esan samba, reggae and jazz, is Ajegunle''s own sound. Producer John ''Mighty Mouse'' Oboh (1967 to 2023) pioneered it, and Ajegunle musicians honour him as the Father of AJ Music.', 'Ajegunle Musicians Honour Mighty Mouse, ''Father of AJ Music'' (The Guardian Nigeria)', 'https://guardian.ng/?p=2908524', 'Which AJ music or galala tune still gets you on your feet?', 'Ajeromi-Ifelodun', 3.33351, 6.448156, 'area', 'high', 'osm:node/13236892517', null, 500, null, false, '/cards/s1/front/AJR-02.webp', '/cards/s1/back/AJR-02.webp', '/cards/s1/thumb/AJR-02.webp', null),
('AJR-03', 'ajeromi-ifelodun', 'Badagry', 'Tolu Schools Complex', 'institution', 'rare', '1981', 'graduate', 'Teaches a small town''s worth of students at once', 'If you school for AJ, Tolu don hear your name before.', 'Tolu Schools Complex in Ajegunle was set up in 1981 to deliver Lagos State''s mass education policy. It now groups 36 public schools in one compound and was recently remodelled.', 'Lagos begins rehabilitation of dilapidated Tolu school complex, Ajegunle (The Guardian Nigeria)', 'https://guardian.ng/news/insecurity-erosion-lagos-begins-rehabilitation-of-dilapidated-tolu-school-complex-ajegunle/', 'What do you remember most about your secondary school days?', 'Ajeromi-Ifelodun', 3.348434, 6.448235, 'place', 'medium', 'osm:way/90288410', null, 150, 1000, false, '/cards/s1/front/AJR-03.webp', '/cards/s1/back/AJR-03.webp', '/cards/s1/thumb/AJR-03.webp', null),
('AJR-IFE-01', 'ifelodun', 'Badagry', 'Mosafejo Council Seat', 'institution', 'common', '2003', 'columns', 'Keeps Amukoko''s paperwork moving', 'Na Mosafejo be the engine room of Ifelodun.', 'Created in 2003 out of Ajeromi-Ifelodun, Ifelodun LCDA runs its council from 3 Dispensary Street, Mosafejo, Amukoko. A second coordinating office sits at Layeni on Ojo Road, near Oja bus stop.', 'Addresses of LSETF Liaison Offices by Local Government (Lagos State Employment Trust Fund)', 'https://lsetf.ng/sites/files/LGAAddressandContactPhoneNumber.pdf', 'What is one thing every Lagos neighbourhood needs from its council?', 'Ifelodun', 3.336764, 6.465696, 'place', 'medium', 'osm:way/167404413', null, 150, null, false, '/cards/s1/front/AJR-IFE-01.webp', '/cards/s1/back/AJR-IFE-01.webp', '/cards/s1/thumb/AJR-IFE-01.webp', null),
('AJR-IFE-02', 'ifelodun', 'Badagry', 'St. Matthew''s Amukoko', 'institution', 'common', 'STMATT', 'church', 'Opens its classroom to every faith', 'For Amukoko, St. Matthew''s gate open for everybody.', 'St. Matthew Catholic Church in Amukoko runs a low-fee school for the community and a training unit for girls, youths and teenage mothers, open to people of every faith. Its justice and peace arm has hosted local peace summits.', 'JDPC holds peace summit in Lagos (The Sun)', 'https://thesun.ng/jdpc-holds-peace-summit-in-lagos/', 'Who in your neighbourhood gives young people a second chance?', 'Ifelodun', 3.342391, 6.469365, 'area', 'low', 'osm:node/14136561163', 'place not found, centre of its area', 500, null, false, '/cards/s1/front/AJR-IFE-02.webp', '/cards/s1/back/AJR-IFE-02.webp', '/cards/s1/thumb/AJR-IFE-02.webp', null),
('ALI-01', 'alimosho', 'Ikeja', 'Biggest Council', 'place', 'common', '1945', 'town', 'Never runs out of new streets', 'If you don enter Alimosho, you don enter plenty Lagos.', 'Alimosho, set up in 1945 under the old Western Region, is widely described as the largest local government in Lagos. The 2006 census counted 1,288,714 people, but Lagos State said the true figure was over 2 million.', 'Alimosho (Wikipedia)', 'https://en.wikipedia.org/wiki/Alimosho', 'How many Lagos LGAs can you name without checking?', 'Alimosho', 3.257588, 6.584388, 'area', 'medium', 'osm:relation/3718185', null, 500, null, false, '/cards/s1/front/ALI-01.webp', '/cards/s1/back/ALI-01.webp', '/cards/s1/thumb/ALI-01.webp', null),
('ALI-AGB-02', 'agbado-oke-odo', 'Ikeja', 'Agege''s Western Edge', 'history', 'common', '1842', 'signpost', 'Stands guard where Lagos meets Egbaland', 'Na Agbado be the old border post. Abeokuta dey the other side.', 'Agbado once marked the western edge of the old Agege territory, where it met Abeokuta district, according to a description tied to an 1842 map of the Lagos district.', 'Agege (Wikipedia)', 'https://en.wikipedia.org/wiki/Agege', 'Where do you think your area''s old border used to be?', 'Agbado/Oke-Odo', 3.259765, 6.677867, 'area', 'medium', 'osm:node/11890939740', null, 500, null, false, '/cards/s1/front/ALI-AGB-02.webp', '/cards/s1/back/ALI-AGB-02.webp', '/cards/s1/thumb/ALI-AGB-02.webp', null),
('ALI-AYO-01', 'ayobo-ipaja', 'Ikeja', 'Old Ayobo', 'history', 'common', 'AYOBO', 'town', 'Remembers Lagos before the expressway', 'Ayobo no be new area, e get deep roots.', 'Ayobo is counted among the old Awori settlements of ancient Agege, alongside Orile, Ogba and Ikola. Local history says these communities came under the authority of the Baale Alaige.', 'Agege (Wikipedia)', 'https://en.wikipedia.org/wiki/Agege', 'What is the oldest family story you know about your area?', 'Ayobo-Ipaja', 3.243794, 6.602034, 'area', 'high', 'osm:node/14161650370', null, 500, null, false, '/cards/s1/front/ALI-AYO-01.webp', '/cards/s1/back/ALI-AYO-01.webp', '/cards/s1/thumb/ALI-AYO-01.webp', null),
('ALI-EGB-01', 'egbe-idimu', 'Ikeja', 'First Council Office', 'history', 'common', 'COUNCIL', 'columns', 'Holds the first key to Alimosho', 'Before Alimosho split into six, na here e start.', 'The first office block of the old single Alimosho Local Government, a two-storey building on Council Street, now lies within Egbe-Idimu LCDA.', 'Alimosho (Wikipedia)', 'https://en.wikipedia.org/wiki/Alimosho', 'Where is the oldest public building in your area?', 'Egbe-Idimu', 3.278228, 6.543748, 'area', 'low', 'osm:node/14161650366', 'place not found, centre of its area', 500, null, false, '/cards/s1/front/ALI-EGB-01.webp', '/cards/s1/back/ALI-EGB-01.webp', '/cards/s1/thumb/ALI-EGB-01.webp', null),
('ALI-EGB-02', 'egbe-idimu', 'Ikeja', 'Kudaki and Akeja', 'history', 'common', 'EGBE', 'town', 'Runs on two family trees and one town spirit', 'Two warriors from Ife plant Egbe. Their families still dey hold am.', 'Local history says Egbe, once called Igbe, was founded in the 17th century by two warriors from Ile-Ife, Kudaki and Akeja. Their descendants make up the town''s two ruling houses.', 'I Had My First Degree at 58 Years (ThisDay via PressReader)', 'https://www.pressreader.com/nigeria/thisday/20171008/281844348849200', 'Which family names in your area go back the furthest?', 'Egbe-Idimu', 3.278228, 6.543748, 'area', 'high', 'osm:node/14161650366', null, 500, null, false, '/cards/s1/front/ALI-EGB-02.webp', '/cards/s1/back/ALI-EGB-02.webp', '/cards/s1/thumb/ALI-EGB-02.webp', null),
('ALI-IGA-01', 'igando-ikotun', 'Ikeja', 'Three Anthills', 'history', 'common', 'IGAN', 'signpost', 'Named by the hardest workers in the bush', 'Na anthill give Igando im name. No be small thing.', 'Local history says Igando was founded about 600 years ago by Bini migrants from Eru-Etan village. The settlers found three anthills, called ''Igan-Odo'' in Yoruba, and the name Igando grew from them.', 'Igando (Wikipedia)', 'https://en.wikipedia.org/wiki/Igando', 'Do you know the story behind your area''s name?', 'Igando-Ikotun', 3.231001, 6.548657, 'area', 'medium', 'osm:node/501496544', null, 500, null, false, '/cards/s1/front/ALI-IGA-01.webp', '/cards/s1/back/ALI-IGA-01.webp', '/cards/s1/thumb/ALI-IGA-01.webp', null),
('ALI-MOS-01', 'mosan-okunola', 'Ikeja', 'Mosan Roots', 'history', 'common', 'MOSAN', 'town', 'Links the new mainland to old Awori roots', 'Mosan get history pass im new estates.', 'Local history says Mosan was one of the communities that later joined the old Awori settlements of ancient Agege, which came under the authority of the Baale Alaige.', 'Agege (Wikipedia)', 'https://en.wikipedia.org/wiki/Agege', 'Which old family names do you still hear in your area?', 'Mosan-Okunola', 3.257588, 6.584388, 'area', 'low', 'osm:relation/3718185', 'Mosan not found, Alimosho stands in', 500, null, false, '/cards/s1/front/ALI-MOS-01.webp', '/cards/s1/back/ALI-MOS-01.webp', '/cards/s1/thumb/ALI-MOS-01.webp', null),
('AMO-03', 'amuwo-odofin', 'Badagry', 'Mile 2', 'place', 'common', 'MILE2', 'terminal', 'Links the Badagry road to the Island by rail', 'Mile 2 to Marina by train? Na so Lagos don change.', 'Mile 2, where the Apapa-Oshodi Expressway meets the Lagos-Badagry Expressway, is the western end of the Blue Line''s first phase, which opened to the public on 4 September 2023 with five stations running to Marina.', 'Lagos Blue Rail (TechCabal)', 'https://techcabal.com/2023/09/05/lagos-blue-rail/', 'Danfo, BRT or train: how do you cross Mile 2?', 'Amuwo-Odofin', 3.311631, 6.459877, 'place', 'high', 'osm:way/1322975948', null, 150, null, false, '/cards/s1/front/AMO-03.webp', '/cards/s1/back/AMO-03.webp', '/cards/s1/thumb/AMO-03.webp', null),
('AMO-ORI-01', 'oriade', 'Badagry', 'Trade Fair Complex', 'place', 'rare', 'FAIR', 'market', 'Sells everything from car parts to gold', 'Anything wey you dey find, Trade Fair get am. Just price am well.', 'Designed by architect Zoran Bojovic and built by Energoprojekt, the Lagos International Trade Fair Complex in Satellite Town covers over 320 hectares. It was commissioned in 1976, ahead of the first Lagos International Trade Fair in 1977.', 'Lagos Trade Fair Complex (Wikipedia)', 'https://en.wikipedia.org/wiki/Lagos_Trade_Fair_Complex', 'What is the best thing you ever bought at a Lagos trade fair?', 'Oriade', 3.246872, 6.463675, 'place', 'high', 'osm:way/733882946', null, 150, 1000, false, '/cards/s1/front/AMO-ORI-01.webp', '/cards/s1/back/AMO-ORI-01.webp', '/cards/s1/thumb/AMO-ORI-01.webp', null),
('AMO-ORI-02', 'oriade', 'Badagry', 'Trade Fair Markets', 'place', 'common', 'ASPMDA', 'market', 'Finds the spare part nobody else can', 'If the car part no dey ASPMDA, e never land Nigeria.', 'In 2002 jewellery, auto spare parts and other traders moved from Balogun Market on Lagos Island into the Trade Fair Complex. It now hosts the Balogun, Progressive and ASPMDA auto spare parts markets.', 'Lagos International Trade Fair Complex (Bureau of Public Enterprises)', 'https://www.bpe.gov.ng/lagos-international-trade-fair-complex/', 'Do you trust your mechanic to buy the part, or do you go to Trade Fair yourself?', 'Oriade', 3.246872, 6.463675, 'area', 'medium', 'osm:way/733882946', null, 500, null, false, '/cards/s1/front/AMO-ORI-02.webp', '/cards/s1/back/AMO-ORI-02.webp', '/cards/s1/thumb/AMO-ORI-02.webp', null),
('APP-02', 'apapa', 'Lagos', 'Apapa Amusement Park', 'culture', 'common', '1976', 'people', 'Turns any Sunday into Christmas', 'Na here plenty Lagos pikin first scream for ride.', 'Apapa Amusement Park opened in 1976 as Lagos Lunar Park, jointly owned by the Lagos Island and Lagos Mainland councils with a Swiss firm, Improjex. It reopened after a full makeover in 2015.', 'Apapa Amusement Park (Wikipedia)', 'https://en.wikipedia.org/wiki/Apapa_Amusement_Park', 'Which fun-fair ride would you queue the longest for?', 'Apapa', 3.366146, 6.443874, 'place', 'high', 'osm:way/738904732', null, 150, null, false, '/cards/s1/front/APP-02.webp', '/cards/s1/back/APP-02.webp', '/cards/s1/thumb/APP-02.webp', null),
('APP-03', 'apapa', 'Lagos', 'Apapa: Fishing Village to Port Town', 'history', 'common', 'GRA', 'port', 'Grew from canoe to container ship', 'Before container, na canoe and fish rule Apapa.', 'Apapa began as a small fishing village of the Awori, a Yoruba subgroup. Under British rule it grew into a port town, with a low-density Government Reserved Area built for colonial administrators and technical staff.', 'Apapa (Wikipedia)', 'https://en.wikipedia.org/wiki/Apapa', 'What do you think Apapa looked like before the port came?', 'Apapa', 3.362237, 6.446905, 'area', 'medium', 'osm:node/13236892516', null, 500, null, false, '/cards/s1/front/APP-03.webp', '/cards/s1/back/APP-03.webp', '/cards/s1/thumb/APP-03.webp', null),
('BDG-WES-01', 'badagry-west', 'Badagry', 'Apa', 'history', 'common', 'APA', 'town', 'Older than the town next door', 'Before Badagry town grow, Apa don dey there.', 'Founded around the 15th century by Awori migrants, Apa is one of the oldest settlements in Badagry Division and has its own Oba, the Alapa of Apa. Most of its people are of Awori and Ogu heritage.', 'Apa, Lagos (Wikipedia)', 'https://en.wikipedia.org/wiki/Apa,_Lagos', 'Which languages do you hear spoken in your family besides English?', 'Badagry West', 2.820229, 6.431883, 'area', 'high', 'osm:node/501366580', null, 500, null, false, '/cards/s1/front/BDG-WES-01.webp', '/cards/s1/back/BDG-WES-01.webp', '/cards/s1/thumb/BDG-WES-01.webp', null),
('BDG-WES-02', 'badagry-west', 'Badagry', 'Seme Border', 'place', 'common', 'SEME', 'gate', 'Opens the road from Lagos to the rest of West Africa', 'One more step from Seme, and you don cross into Benin.', 'The Gbaji-Seme axis of Badagry West links Nigeria to Benin Republic at the Seme international border, a major customs revenue point. A 2015 report counted over 50 communities and about 200,000 residents along the corridor.', '50 Lagos communities lived without electricity for 16 years (Vanguard)', 'https://www.vanguardngr.com/2015/11/50-lagos-communities-lived-without-electricity-for-16-years/', 'Have you ever travelled to another country by road? Where to?', 'Badagry West', 2.722388, 6.3821, 'place', 'high', 'osm:node/14056882944', null, 150, null, false, '/cards/s1/front/BDG-WES-02.webp', '/cards/s1/back/BDG-WES-02.webp', '/cards/s1/thumb/BDG-WES-02.webp', null),
('EPE-02', 'epe', 'Epe', 'Kayo-Kayo Festival', 'culture', 'common', '1851', 'mosque', 'Brings the whole of Epe home once a year', 'Who dey Epe for Kayo-Kayo week? The whole town go dey there.', 'Kayo-Kayo is a yearly cultural and religious festival in Epe, celebrated by descendants of Oba Kosoko to mark his arrival in Epe in 1851. It is usually held in the first Islamic month, around Ashura.', 'Kayo-Kayo Festival (Wikipedia)', 'https://en.wikipedia.org/wiki/Kayo-Kayo_Festival', 'Which festival makes you travel back to your hometown?', 'Epe', 3.975694, 6.585729, 'area', 'medium', 'osm:relation/3718189', null, 500, null, false, '/cards/s1/front/EPE-02.webp', '/cards/s1/back/EPE-02.webp', '/cards/s1/thumb/EPE-02.webp', null),
('EPE-03', 'epe', 'Epe', 'Epe Barge Builders', 'history', 'common', 'BARGE', 'port', 'Builds the boats that carry the lagoon trade', 'Na Epe hand build the boats wey dey run the lagoon.', 'Epe was set up by the mid-18th century as the chief port for Ijebu-Ode, trading cloth and farm produce. Britannica says the town is best known for building the motorised, shallow-draft barges that move along the coastal lagoons.', 'Epe (Britannica)', 'https://www.britannica.com/place/Epe', 'Have you ever crossed a Lagos lagoon by boat?', 'Epe', 3.975694, 6.585729, 'area', 'medium', 'osm:relation/3718189', null, 500, null, false, '/cards/s1/front/EPE-03.webp', '/cards/s1/back/EPE-03.webp', '/cards/s1/thumb/EPE-03.webp', null),
('EPE-ERE-02', 'eredo', 'Epe', 'Alara of Ilara-Epe', 'history', 'common', 'ALARA', 'crown', 'Keeps the crown steady for generations', 'Na Ilara wait 60 years before e see another crowning.', 'In 2020 Ilara-Epe installed a new Alara, its first coronation in about 60 years. The previous king, Oba Akeem Okunola Adesanya II, reigned 58 years until October 2018 and was then the longest reigning monarch in Lagos State.', '60 years after, Ilara-Epe savours kingship rituals (The Guardian Nigeria)', 'https://guardian.ng/sunday-magazine/newsfeature/60-years-after-ilara-epe-savours-kingship-rituals/', 'What is the oldest tradition your family still keeps?', 'Eredo', 3.975694, 6.585729, 'area', 'low', 'osm:relation/3718189', 'Ilara not found, Epe stands in', 500, null, false, '/cards/s1/front/EPE-ERE-02.webp', '/cards/s1/back/EPE-ERE-02.webp', '/cards/s1/thumb/EPE-ERE-02.webp', null),
('EPE-IKO-01', 'ikosi-ejinrin', 'Epe', 'Ejinrin Lagoon Market', 'place', 'rare', '1908', 'market', 'Sent the palm oil that Lagos shipped to the world', 'Before Balogun or Oyingbo, na Ejinrin be the market wey everybody sabi.', 'Ejinrin was a great market on the north bank of the Lagos Lagoon. Colonial records counted 20,000 to 26,000 people on a market day by the late 1800s, and by 1908 it was rated the largest market in Nigeria''s western provinces.', 'Trade on the North Eastern Bank of the Lagos Lagoon: A Focus on Ejinrin Lagoon Market, 1851 to 1939 (Yoruba Studies Review)', 'https://journals.flvc.org/ysr/article/view/129848', 'What market did your parents always go to when you were young?', 'Ikosi-Ejinrin', 3.975694, 6.585729, 'area', 'low', 'osm:relation/3718189', 'place and Ejinrin not found, Epe stands in', 500, 1000, false, '/cards/s1/front/EPE-IKO-01.webp', '/cards/s1/back/EPE-IKO-01.webp', '/cards/s1/thumb/EPE-IKO-01.webp', null),
('EPE-IKO-02', 'ikosi-ejinrin', 'Epe', 'Agbowa Refuge Town', 'history', 'common', 'AGO', 'tree', 'Makes room for everybody who knocks', 'Na Agbowa open door when war scatter the neighbours.', 'Local history says Agbowa-Ikosi sheltered people from Imota, Ibefun, Ota and Owu during the old wars, who settled in quarters called Ago-Mota, Ago-Ibefun, Ago-Ota and Ago-Owu. The town was also headquarters of the old Ikosi District Council.', 'Agbowa-Ikosi (Wikipedia)', 'https://en.wikipedia.org/wiki/Agbowa-Ikosi', 'Who is the most welcoming person you know in Lagos?', 'Ikosi-Ejinrin', 3.712314, 6.643289, 'area', 'high', 'osm:node/501430594', null, 500, null, false, '/cards/s1/front/EPE-IKO-02.webp', '/cards/s1/back/EPE-IKO-02.webp', '/cards/s1/thumb/EPE-IKO-02.webp', null),
('ETO-IKY-02', 'ikoyi-obalende', 'Lagos', 'Ikoyi Club 1938', 'institution', 'rare', '1938', 'seal', 'Mixes the first glass of Chapman', 'Na here Chapman first enter glass, local history talk am.', 'Ikoyi Club 1938 dates its founding to 29 September 1938, when the European Club and the Lagos Golf Club came together. Wikipedia credits the Chapman cocktail to Sam Alamutu, who first mixed it on the club grounds.', 'Ikoyi Club 1938 Celebrates 78th Anniversary (ThisDay)', 'https://thisdaylive.com/index.php/2016/09/24/ikoyi-club-1938-celebrates-78th-anniversary', 'Chapman or Zobo: which one wins at a Lagos party?', 'Ikoyi-Obalende', 3.427907, 6.452013, 'place', 'high', 'osm:way/505948214', null, 150, 1000, false, '/cards/s1/front/ETO-IKY-02.webp', '/cards/s1/back/ETO-IKY-02.webp', '/cards/s1/thumb/ETO-IKY-02.webp', null),
('ETO-IKY-03', 'ikoyi-obalende', 'Lagos', 'Dodan Barracks', 'history', 'rare', 'DODAN', 'columns', 'Kept the keys to the country for decades', 'Na here Naija power sleep for over twenty years.', 'Dodan Barracks in Ikoyi, named after a Second World War battle site in Burma, was Nigeria''s seat of government under military rule from 1966. The seat of government moved from there to Abuja on 12 December 1991.', 'Ikoyi (Wikipedia)', 'https://en.wikipedia.org/wiki/Ikoyi', 'Which Lagos building do you think has seen the most history?', 'Ikoyi-Obalende', 3.418749, 6.450752, 'place', 'medium', 'osm:way/551350562', 'moved about 120 m to a viewpoint outside the military zone', 300, 1000, false, '/cards/s1/front/ETO-IKY-03.webp', '/cards/s1/back/ETO-IKY-03.webp', '/cards/s1/thumb/ETO-IKY-03.webp', null),
('IBL-03', 'ibeju-lekki', 'Epe', 'Akodo Beach', 'place', 'common', 'AKODO', 'beach', 'Gives the Atlantic its own guest house', 'Akodo sand soft pass your bedsheet, ask anybody wey don go.', 'Eko Tourist Beach Resort, also called Akodo Beach, was developed at Akodo by the Lagos State government in the 1990s. It sits on about 10 acres with chalets, restaurants and more than half a mile of beach.', 'The Making of Lekki Tourism Zone (ThisDay)', 'https://thisdaylive.com/index.php/2016/04/23/the-making-of-lekki-tourism-zone', 'Beach day: do you swim or do you just sit and gist?', 'Ibeju-Lekki', 3.930266, 6.435457, 'area', 'low', 'osm:node/501329985', 'place not found, centre of its area', 500, null, false, '/cards/s1/front/IBL-03.webp', '/cards/s1/back/IBL-03.webp', '/cards/s1/thumb/IBL-03.webp', null),
('IBL-LEK-01', 'lekki', 'Epe', 'Awo Detention Camp', 'history', 'rare', '1962', 'gate', 'Turns a place of detention into a place of learning', 'Local history says Awo pray for this town and the prayer catch.', 'In 1962 Chief Obafemi Awolowo was restricted to a government rest house in Lekki Town, a site later called the Awolowo Detention Camp. Lagos State remodelled it as an institute in June 2009.', 'Awolowo Detention Camp (Wikipedia)', 'https://en.wikipedia.org/wiki/Awolowo_Detention_Camp', 'Which Nigerian leader from history would you most like to interview?', 'Lekki', 3.483247, 6.466153, 'area', 'low', 'osm:node/13176785059', 'place not found, centre of its area', 500, 1000, false, '/cards/s1/front/IBL-LEK-01.webp', '/cards/s1/back/IBL-LEK-01.webp', '/cards/s1/thumb/IBL-LEK-01.webp', null),
('IFK-01', 'ifako-ijaiye', 'Ikeja', 'Born 1996', 'history', 'common', '1996', 'seal', 'Guards the Lagos side of the Ogun border', 'One leg for Lagos, the other near Ogun. Na Ifako style.', 'Ifako-Ijaiye Local Government was created on 1 October 1996, carved out of Agege, with its headquarters at Ifako. It is a border area that shares a boundary with Ogun State.', 'Ifako-Ijaiye (Wikipedia)', 'https://en.wikipedia.org/wiki/Ifako-Ijaiye', 'Which border town have you crossed from Lagos into Ogun?', 'Ifako-Ijaiye', 3.289491, 6.663603, 'area', 'medium', 'osm:node/501513101', null, 500, null, false, '/cards/s1/front/IFK-01.webp', '/cards/s1/back/IFK-01.webp', '/cards/s1/thumb/IFK-01.webp', null),
('IFK-02', 'ifako-ijaiye', 'Ikeja', 'Iju Waterworks', 'institution', 'rare', '1910', 'tap', 'Has filled Lagos buckets for over a century', 'Before sachet water, na Iju dey pour Lagos tap.', 'Iju Waterworks was Lagos''s first piped water scheme, built mainly to serve colonial residents of Ikoyi. Its first plant, from 1910, drew spring water from the Iju hills at about 2.4 million gallons a day.', 'A Background of Water Management in Lagos (Lafayette College Hydronarratives)', 'https://scalar.lafayette.edu/hydronarratives/media/analysis-of-water-production-in-lagos', 'Where does the water in your house come from?', 'Ifako-Ijaiye', 3.324671, 6.650746, 'area', 'low', 'osm:node/14161627787', 'Iju Water Works is just across the border in Ogun State, so Iju stands in', 500, 1000, false, '/cards/s1/front/IFK-02.webp', '/cards/s1/back/IFK-02.webp', '/cards/s1/thumb/IFK-02.webp', null),
('IFK-OJK-01', 'ojokoro', 'Ikeja', 'Village of the Egba', 'history', 'common', 'EGBA', 'signpost', 'Carries Abeokuta in its name', 'Egba people land first, Abule Egba carry the name.', 'Abule Egba was first called ''Abule awon Egba'', Yoruba for ''village of the Egba people'', after early settlers who came from Abeokuta, local history says.', 'History behind the names of 10 popular places in Lagos (Ripples Nigeria)', 'https://ripplesnigeria.com/history-behind-the-names-of-10-popular-places-in-lagos', 'Does your area''s name tell you who settled there first?', 'Ojokoro', 3.304622, 6.647894, 'area', 'medium', 'osm:node/501527950', null, 500, null, false, '/cards/s1/front/IFK-OJK-01.webp', '/cards/s1/back/IFK-OJK-01.webp', '/cards/s1/thumb/IFK-OJK-01.webp', null),
('IFK-OJK-03', 'ojokoro', 'Ikeja', 'Oko-Oba Abattoir', 'food', 'common', 'OKOOBA', 'market', 'Keeps Lagos pots full of meat', 'Your Sunday stew meat fit don pass Oko-Oba first.', 'The Lagos State Central Abattoir at Oko-Oba is the largest of the state''s eight authorised abattoirs. BusinessDay reports that over 30 percent of the roughly 8,000 cattle and ruminants eaten in Lagos daily are slaughtered there.', 'Oko-Oba abattoir report (BusinessDay)', 'https://businessday.ng/?p=211566', 'Suya, asun or pepper soup: which Lagos meat dish wins?', 'Ojokoro', 3.319375, 6.65015, 'place', 'medium', 'osm:way/707657152', null, 150, null, false, '/cards/s1/front/IFK-OJK-03.webp', '/cards/s1/back/IFK-OJK-03.webp', '/cards/s1/thumb/IFK-OJK-03.webp', null),
('IKD-IGB-01', 'igbogbo-baiyeku', 'Ikorodu', 'The Adeboruwa Throne', 'history', 'common', 'IGBOGBO', 'crown', 'Summons chiefs, drummers and visitors with one palace call', 'Igbogbo no be just area o, na full kingdom with royal paperwork.', 'Igbogbo is a kingdom whose Oba is styled the Adeboruwa of Igbogbo. Its council area, Igbogbo/Bayeku LCDA, is one of the units carved out of the old Ikorodu LGA in 2003.', 'Dignitaries celebrate Adeboruwa''s 10 years on throne (The Guardian Nigeria)', 'https://guardian.ng/?p=2885938', 'What makes a town feel like a kingdom and not just a neighbourhood?', 'Igbogbo-Baiyeku', 3.517127, 6.591307, 'area', 'high', 'osm:node/501463673', null, 500, null, false, '/cards/s1/front/IKD-IGB-01.webp', '/cards/s1/back/IKD-IGB-01.webp', '/cards/s1/thumb/IKD-IGB-01.webp', null),
('IKD-IGB-03', 'igbogbo-baiyeku', 'Ikorodu', 'Igbogbo Day', 'culture', 'common', 'DAY 30', 'mask', 'Pulls Igbogbo sons and daughters home from anywhere', 'Thirty editions in and Igbogbo still knows how to throw a party with heritage.', 'Igbogbo Day is the kingdom''s yearly cultural celebration. Its 30th edition ended with a packed grand finale at the town stadium, themed ''A festival of new opportunities, land of Cool beauty''.', 'Igbogbo''s rich cultural heritage on display at festival (The Guardian Nigeria)', 'https://guardian.ng/?p=827752', 'Which hometown celebration would you travel the furthest to attend?', 'Igbogbo-Baiyeku', 3.517127, 6.591307, 'area', 'high', 'osm:node/501463673', null, 500, null, false, '/cards/s1/front/IKD-IGB-03.webp', '/cards/s1/back/IKD-IGB-03.webp', '/cards/s1/thumb/IKD-IGB-03.webp', null),
('IKD-IGB-04', 'igbogbo-baiyeku', 'Ikorodu', 'The New Adeboruwa Palace', 'place', 'common', 'PALACE', 'crown', 'Turns any visit into a royal audience', 'New palace, same royal energy. Greet well when you enter o.', 'A newly built Adeboruwa of Igbogbo Palace was commissioned for the Lagos State Government, which described the building as a beacon of shared history.', 'Sanwo-Olu commissions Adeboruwa of Igbogbo Palace (BusinessDay)', 'https://businessday.ng/?p=1000577', 'What should every palace have that a regular building does not?', 'Igbogbo-Baiyeku', 3.517127, 6.591307, 'area', 'low', 'osm:node/501463673', 'place not found, centre of its area', 500, null, false, '/cards/s1/front/IKD-IGB-04.webp', '/cards/s1/back/IKD-IGB-04.webp', '/cards/s1/thumb/IKD-IGB-04.webp', null),
('IKD-IGB-05', 'igbogbo-baiyeku', 'Ikorodu', 'Adeboruwa Market', 'place', 'common', '200', 'market', 'Turns one shopping list into two hundred options', 'Two hundred shops means two hundred chances to price am well.', 'Igbogbo has a 200-shop Adeboruwa Market, built through a public-private partnership by the Igbogbo/Baiyeku LCDA.', 'As Igbogbo soars under Oba Kasali (Blueprint)', 'https://blueprint.ng/as-igbogbo-soars-under-oba-kasali/', 'What is the one stall every Lagos market needs?', 'Igbogbo-Baiyeku', 3.517127, 6.591307, 'area', 'low', 'osm:node/501463673', 'place not found, centre of its area', 500, null, false, '/cards/s1/front/IKD-IGB-05.webp', '/cards/s1/back/IKD-IGB-05.webp', '/cards/s1/thumb/IKD-IGB-05.webp', null),
('IKD-IGB-06', 'igbogbo-baiyeku', 'Ikorodu', 'Baiyeku Jetty', 'place', 'common', 'JETTY', 'jetty', 'Skips road traffic by taking the water way', 'Traffic who? Baiyeku said make we try the water route.', 'In June 2020, Lagos handed the newly built Baiyeku Concrete Jetty in Ikorodu over to the Lagos State Waterways Authority (LASWA) to improve water transport in the area.', 'Lagos hands over Baiyeku Jetty to LASWA (BrandSpur)', 'https://brandspurng.com/2020/06/26/lagos-hands-over-baiyeku-jetty-to-laswa-photos/', 'Would you swap your bus commute for a boat ride? Why or why not?', 'Igbogbo-Baiyeku', 3.552964, 6.536588, 'place', 'medium', 'osm:node/6274197913', 'moved about 60 m to a viewpoint outside the water zone', 300, null, false, '/cards/s1/front/IKD-IGB-06.webp', '/cards/s1/back/IKD-IGB-06.webp', '/cards/s1/thumb/IKD-IGB-06.webp', null),
('IKD-IGB-07', 'igbogbo-baiyeku', 'Ikorodu', 'Ikorodu''s 1865 Ally', 'history', 'rare', '1865', 'seal', 'Shows up for the neighbours when it matters', 'When Ikorodu called for backup, Igbogbo picked up first.', 'A 2021 Yoruba Studies Review article credits Balogun Jaiyesimi''s diplomacy with forming a coalition of Ikorodu and its neighbours, especially Igbogbo, against the 1864 to 1865 Egba attack on Ikorodu.', 'Trade, Violence and Diplomacy on the Coast of Ikorodu (Yoruba Studies Review)', 'https://journals.flvc.org/ysr/article/view/129844', 'Which neighbouring area would you call first if you needed backup?', 'Igbogbo-Baiyeku', 3.517127, 6.591307, 'area', 'high', 'osm:node/501463673', null, 500, 1000, false, '/cards/s1/front/IKD-IGB-07.webp', '/cards/s1/back/IKD-IGB-07.webp', '/cards/s1/thumb/IKD-IGB-07.webp', null),
('IKD-IGB-09', 'igbogbo-baiyeku', 'Ikorodu', 'Zumratul Grammar School', 'institution', 'common', 'ZGS', 'graduate', 'Keeps Igbogbo''s study culture strong', 'Books, discipline and a 90-year-old society behind you. Serious business.', 'Igbogbo has a grammar school set up by the Zumratul Islamiyyah Society, an Islamic society that marked its 90th anniversary in 2018.', 'Zumratul Islamiyyah marks 90th anniversary (Daily Trust)', 'https://www.pressreader.com/nigeria/daily-trust/20180105/281878708760101', 'Which school in your area has the most famous old students?', 'Igbogbo-Baiyeku', 3.522648, 6.587963, 'place', 'high', 'osm:way/680466348', null, 150, null, false, '/cards/s1/front/IKD-IGB-09.webp', '/cards/s1/back/IKD-IGB-09.webp', '/cards/s1/thumb/IKD-IGB-09.webp', null),
('IKD-IGB-10', 'igbogbo-baiyeku', 'Ikorodu', 'The Monarch''s History Book', 'culture', 'common', 'BOOK', 'scroll', 'Keeps Igbogbo''s story safe between two covers', 'Kabiyesi no just make history, him write am down too.', 'At his 10th coronation anniversary in July 2026, the Adeboruwa launched his book, The Town, the Throne, and Transformations, which documents the history of Igbogbo Kingdom.', 'Dignitaries celebrate Adeboruwa''s 10 years on throne (The Guardian Nigeria)', 'https://guardian.ng/?p=2885938', 'If your area got its own history book, which chapter would you write?', 'Igbogbo-Baiyeku', 3.517127, 6.591307, 'area', 'high', 'osm:node/501463673', null, 500, null, false, '/cards/s1/front/IKD-IGB-10.webp', '/cards/s1/back/IKD-IGB-10.webp', '/cards/s1/thumb/IKD-IGB-10.webp', null),
('IKD-IJD-01', 'ijede', 'Ikorodu', 'Egbin Power Station', 'place', 'rare', '1320MW', 'power', 'Keeps fans spinning across the national grid', 'Six units, one big job: keep the fan spinning.', 'Egbin Power Station at Egbin/Ijede has six 220 MW units, giving it 1,320 MW of installed capacity. Its first unit came online in 1985.', 'Egbin Thermal Power Station (Wikipedia)', 'https://en.wikipedia.org/wiki/Egbin_Thermal_Power_Station', 'What is the first thing you switch on when the light comes back?', 'Ijede', 3.617426, 6.56403, 'place', 'medium', 'osm:way/669973420', 'moved about 300 m to a viewpoint outside the power zone', 300, 1000, false, '/cards/s1/front/IKD-IJD-01.webp', '/cards/s1/back/IKD-IJD-01.webp', '/cards/s1/thumb/IKD-IJD-01.webp', null),
('IKD-IJD-02', 'ijede', 'Ikorodu', 'Egbin Goes Private', 'history', 'common', '2013', 'power', 'Turns a public plant into a private powerhouse', 'Same Egbin, new landlords. The turbines no even notice.', 'In November 2013, Egbin was handed to a joint venture of Sahara Power Group and South Korea''s KEPCO under the privatisation of Nigeria''s power sector.', 'About Egbin Power (Egbin Power Plc)', 'https://egbin-power.com/about/', 'If you owned a power plant, what would you name it?', 'Ijede', 3.600196, 6.560216, 'area', 'medium', 'osm:node/13749481237', null, 500, null, false, '/cards/s1/front/IKD-IJD-02.webp', '/cards/s1/back/IKD-IJD-02.webp', '/cards/s1/thumb/IKD-IJD-02.webp', null),
('IKD-IJD-03', 'ijede', 'Ikorodu', 'Ijede General Hospital', 'institution', 'common', 'IGH', 'hospital', 'Upgrades itself from clinic to hospital', 'Started small in 1983, now na full general hospital. Ijede grow am well.', 'Ijede General Hospital, on Egbin Thermal Power Station Road, began as a primary health centre in 1983 and officially became a general hospital in 2012.', 'Quality Healthcare is Local: The Ijede General Hospital Story (Nigeria Health Watch)', 'https://nigeriahealthwatch.com/uncategorized/quality-healthcare-is-local-the-ijede-general-hospital-story/', 'What service would you add first to your local hospital?', 'Ijede', 3.596555, 6.564733, 'place', 'high', 'osm:way/746008852', null, 150, null, false, '/cards/s1/front/IKD-IJD-03.webp', '/cards/s1/back/IKD-IJD-03.webp', '/cards/s1/thumb/IKD-IJD-03.webp', null),
('IKD-IJD-04', 'ijede', 'Ikorodu', 'Ijede Spring', 'place', 'rare', 'SPRING', 'tap', 'Makes a quiet stream feel like a holiday', 'Ijede get its own spring. Nobody tell Ikogosi.', 'Ijede Spring, also called Odoro spring, is listed by Lagos State as a gazetted tourism site. Its stream runs beside a beach before emptying into the Lagos Lagoon.', 'Ijede spring (Wikipedia)', 'https://en.wikipedia.org/wiki/Ijede_spring', 'What hidden natural spot in Lagos should more people know about?', 'Ijede', 3.591864, 6.565579, 'area', 'low', 'osm:node/501463454', 'place not found, centre of its area', 500, 1000, false, '/cards/s1/front/IKD-IJD-04.webp', '/cards/s1/back/IKD-IJD-04.webp', '/cards/s1/thumb/IKD-IJD-04.webp', null),
('IKD-IJD-05', 'ijede', 'Ikorodu', 'Baba Odoro', 'lore', 'common', 'ODORO', 'tap', 'Finds water when everybody else don give up', 'Drought come, Baba Odoro find water. Legend behaviour.', 'Local tradition credits an elder, Baba Odoro, with discovering Ijede''s spring during a severe drought, which is why it is also known as Odoro spring.', 'List of cultural assets in Lagos (Wikipedia)', 'https://en.wikipedia.org/wiki/List_of_cultural_assets_in_Lagos', 'Who is the legendary elder people still talk about in your area?', 'Ijede', 3.591864, 6.565579, 'area', 'high', 'osm:node/501463454', null, 500, null, false, '/cards/s1/front/IKD-IJD-05.webp', '/cards/s1/back/IKD-IJD-05.webp', '/cards/s1/thumb/IKD-IJD-05.webp', null),
('IKD-IJD-06', 'ijede', 'Ikorodu', 'Eyibi Festival', 'culture', 'common', 'EYIBI', 'mask', 'Renews community bonds every single year', 'Respect the rites, respect the elders, and check the dates before you plan.', 'Oke Eletu in Ijede LCDA holds the yearly Eyibi Festival, focused on unity, peace and spiritual renewal. The 2024 edition opened on 15 October with the Ituworo ceremony.', 'Eyibi Festival (Wikipedia)', 'https://en.wikipedia.org/wiki/Eyibi_Festival', 'How does your community mark a fresh start each year?', 'Ijede', 3.587956, 6.602567, 'area', 'medium', 'osm:way/742652352', null, 500, null, false, '/cards/s1/front/IKD-IJD-06.webp', '/cards/s1/back/IKD-IJD-06.webp', '/cards/s1/thumb/IKD-IJD-06.webp', null),
('IKD-IJD-07', 'ijede', 'Ikorodu', 'Egbin Royal Palace', 'place', 'common', 'EGBIN', 'crown', 'Hosts royalty and megawatts on the same street', 'Royal palace on one side, power station on the other. Egbin get range.', 'The Obateru of Egbin''s Royal Palace, centre of traditional authority for the Egbin Kingdom in Ijede LCDA, stands opposite the Lagos Lagoon next to the Egbin power station.', 'Obateru of Egbin''s Royal Palace (Wikipedia)', 'https://en.wikipedia.org/wiki/Obateru_of_Egbin%27s_Royal_Palace', 'What would you put in a museum about your area''s history?', 'Ijede', 3.600196, 6.560216, 'area', 'low', 'osm:node/13749481237', 'place not found, centre of its area', 500, null, false, '/cards/s1/front/IKD-IJD-07.webp', '/cards/s1/back/IKD-IJD-07.webp', '/cards/s1/thumb/IKD-IJD-07.webp', null),
('IKD-IJD-08', 'ijede', 'Ikorodu', 'Ijede Since 1937', 'history', 'common', '1937', 'seal', 'Survives every map redraw since 1937', 'Ijede don dey run council business since 1937. Senior council, abeg.', 'Ijede''s local government story starts with the Ijede Native Authority of 1937. An Ijede Local Council was gazetted in 1952, and Ijede became an LCDA in 2003.', 'Ijede (Wikipedia)', 'https://en.wikipedia.org/wiki/Ijede', 'What is the oldest thing in your area that still works?', 'Ijede', 3.591864, 6.565579, 'area', 'high', 'osm:node/501463454', null, 500, null, false, '/cards/s1/front/IKD-IJD-08.webp', '/cards/s1/back/IKD-IJD-08.webp', '/cards/s1/thumb/IKD-IJD-08.webp', null),
('IKD-IJD-09', 'ijede', 'Ikorodu', 'Ijede''s Farm Villages', 'place', 'common', 'FARMS', 'farm', 'Feeds the neighbourhood straight from the farm', 'One LCDA, plenty villages, everybody get farm story.', 'Ijede LCDA takes in communities such as Ijede, Egbin, Oke Eletu, Ginti, Igbodu, Abule Eko, Igbopa and Ayetoro, whose people are traditionally farmers.', 'Ijede (Wikipedia)', 'https://en.wikipedia.org/wiki/Ijede', 'Which of these community names would you love to know the story behind?', 'Ijede', 3.591864, 6.565579, 'area', 'medium', 'osm:node/501463454', null, 500, null, false, '/cards/s1/front/IKD-IJD-09.webp', '/cards/s1/back/IKD-IJD-09.webp', '/cards/s1/thumb/IKD-IJD-09.webp', null),
('IKD-IKO-01', 'ikorodu', 'Ikorodu', 'Oga the Hunter', 'history', 'rare', 'OGA', 'staff', 'Turns one hunting trip into a whole kingdom', 'One elephant, one hunter, one whole town. Talk about a first impression.', 'Local history says Ikorodu was founded by Oga, a hunter from Offin in Sagamu, who killed a dangerous elephant on the Oko Odu farmland and later returned with his brothers Lasunwon and Rademo to settle.', 'The genesis of Ikorodu (Daily Trust)', 'https://dailytrust.com/the-genesis-of-ikorodu', 'If you founded a town today, what would people name it after?', 'Ikorodu', 3.504127, 6.619123, 'area', 'medium', 'osm:relation/3718194', null, 500, 1000, false, '/cards/s1/front/IKD-IKO-01.webp', '/cards/s1/back/IKD-IKO-01.webp', '/cards/s1/thumb/IKD-IKO-01.webp', null),
('IKD-IKO-02', 'ikorodu', 'Ikorodu', 'Oko Odu: The Odu Farm', 'history', 'common', 'ODU', 'farm', 'Dyes any cloth deep and dark', 'Started as a dye farm, became a big city. Ikorodu always knew how to add colour.', 'The name Ikorodu is traced to Oko Odu, Yoruba for ''Odu farm''. Odu was a plant used to dye cloth, and the Remo accent turned Oko Odu into Okorodu, which later became Ikorodu.', 'The genesis of Ikorodu (Daily Trust)', 'https://dailytrust.com/the-genesis-of-ikorodu', 'Which Lagos place name do you think has the best origin story?', 'Ikorodu', 3.504127, 6.619123, 'area', 'medium', 'osm:relation/3718194', null, 500, null, false, '/cards/s1/front/IKD-IKO-02.webp', '/cards/s1/back/IKD-IKO-02.webp', '/cards/s1/thumb/IKD-IKO-02.webp', null),
('IKD-IKO-04', 'ikorodu', 'Ikorodu', 'The Ayangburen''s Palace', 'place', 'rare', 'AYAN', 'crown', 'Hosts royal banquets without breaking a sweat', 'Built by the people, for the crown. Na teamwork make the dream work.', 'The Ayangburen is the paramount traditional ruler of Ikorodu. A new palace for the throne was commissioned in August 2018, built by Ikorodu indigenes and well-wishers of the community.', 'Ambode commissions new Ayangburen palace (Vanguard)', 'https://www.vanguardngr.com/2018/08/ambode-commissions-new-ayangburen-palace-marks-three-years-on-throne/', 'What would you ask a king if you had five minutes in his palace?', 'Ikorodu', 3.501668, 6.61566, 'place', 'medium', 'osm:way/742039109', null, 150, 1000, false, '/cards/s1/front/IKD-IKO-04.webp', '/cards/s1/back/IKD-IKO-04.webp', '/cards/s1/thumb/IKD-IKO-04.webp', null),
('IKD-IKO-05', 'ikorodu', 'Ikorodu', 'Lasunwon and Rademo', 'history', 'common', 'L + R', 'town', 'Keeps the royal family tree in perfect order', 'Two royal houses, three quarters, one town. The maths is mathing.', 'Ikorodu''s traditional town is grouped into three main quarters, Ijomu, Aga and Isele, and the right to the Ikorodu throne belongs to two royal families, Lasunwon and Rademo.', 'Trade, Violence and Diplomacy on the Coast of Ikorodu (Yoruba Studies Review, 2021)', 'https://journals.flvc.org/ysr/article/download/129844/132264/226137', 'Do you know which quarter or family compound your people come from?', 'Ikorodu', 3.504127, 6.619123, 'area', 'medium', 'osm:relation/3718194', null, 500, null, false, '/cards/s1/front/IKD-IKO-05.webp', '/cards/s1/back/IKD-IKO-05.webp', '/cards/s1/thumb/IKD-IKO-05.webp', null),
('IKD-IKO-06', 'ikorodu', 'Ikorodu', 'Battle of Ikorodu, 1865', 'history', 'rare', '1865', 'seal', 'Builds alliances faster than enemies can march', 'Ikorodu told a whole army ''not today''. Respect the coast.', 'In 1865 an Egba army attacking Ikorodu was defeated. Britannica credits troops from Lagos, while a 2021 study credits war chief Balogun Mabadeje Jaiyesimi and his alliance with nearby Igbogbo.', 'Trade, Violence and Diplomacy on the Coast of Ikorodu (Yoruba Studies Review)', 'https://journals.flvc.org/ysr/article/view/129844', 'When a town wins a battle, who deserves the credit: the generals or the people?', 'Ikorodu', 3.504127, 6.619123, 'area', 'medium', 'osm:relation/3718194', null, 500, 1000, false, '/cards/s1/front/IKD-IKO-06.webp', '/cards/s1/back/IKD-IKO-06.webp', '/cards/s1/thumb/IKD-IKO-06.webp', null),
('IKD-IKO-07', 'ikorodu', 'Ikorodu', 'Ceded to the Crown, 1894', 'history', 'rare', '1894', 'scroll', 'Redraws a state boundary with one signature', 'One treaty later, Ikorodu was officially on the Lagos side of the map.', 'After Britain defeated Ijebu in 1892, its lagoon territory passed to the British Crown by two treaties: Epe in 1892, then Ikorodu and its surroundings in 1894. This set the eastern edge of today''s Lagos State.', 'British Annexation of Epe and Ikorodu, 1892-94 (University of Lagos repository)', 'https://ir.unilag.edu.ng/handle/123456789/7599', 'How different would Lagos be if Ikorodu had never joined it?', 'Ikorodu', 3.504127, 6.619123, 'area', 'medium', 'osm:relation/3718194', null, 500, 1000, false, '/cards/s1/front/IKD-IKO-07.webp', '/cards/s1/back/IKD-IKO-07.webp', '/cards/s1/thumb/IKD-IKO-07.webp', null),
('IKD-IKO-08', 'ikorodu', 'Ikorodu', 'The I in IBILE', 'history', 'rare', 'IBILE', 'town', 'Holds down a letter in the most famous Lagos acronym', 'Without Ikorodu, IBILE na just BILE. Nobody wants that.', 'IBILE stands for Lagos State''s five administrative divisions: Ikeja, Badagry, Ikorodu, Lagos and Epe. An edict of April 1968 created them, making Ikorodu one of the five.', 'Lagos Speaker, Lawmakers at Loggerheads over Administrative Divisions Bill (ThisDay)', 'https://www.thisdaylive.com/2021/02/21/lagos-speaker-lawmakers-at-loggerheads-over-administrative-divisions-bill/', 'Can you name all five IBILE divisions without checking your phone?', 'Ikorodu', 3.504127, 6.619123, 'area', 'medium', 'osm:relation/3718194', null, 500, 1000, false, '/cards/s1/front/IKD-IKO-08.webp', '/cards/s1/back/IKD-IKO-08.webp', '/cards/s1/thumb/IKD-IKO-08.webp', null),
('IKD-IKO-10', 'ikorodu', 'Ikorodu', 'Ikorodu Oga Festival', 'culture', 'rare', 'FEST', 'mask', 'Turns a whole town into one big carnival', 'A whole week of carnival in Ikorodu. Clear your calendar and charge your phone.', 'Launched in 1992, the Ikorodu Oga Festival celebrates the town''s heritage, usually over a week of processions with traditional dancers, musicians and masquerades.', 'Ikorodu Oga Festival (Wikipedia)', 'https://en.wikipedia.org/wiki/Ikorodu_Oga_Festival', 'Which hometown festival would you travel back for, no matter what?', 'Ikorodu', 3.504127, 6.619123, 'area', 'medium', 'osm:relation/3718194', null, 500, 1000, false, '/cards/s1/front/IKD-IKO-10.webp', '/cards/s1/back/IKD-IKO-10.webp', '/cards/s1/thumb/IKD-IKO-10.webp', null),
('IKD-IKO-11', 'ikorodu', 'Ikorodu', 'Oro Day', 'culture', 'common', 'ORO', 'mask', 'Brings a busy town to a respectful pause', 'On Oro day, Ikorodu keeps its traditions close. Plan your errands early.', 'Oro is a sacred Yoruba tradition kept by male indigenes. In Ikorodu, Oro day falls during the Magbo festival, and custom asks women to stay indoors while the rites take place.', 'Female ban during Nigerian festival causes uproar (News24 / AFP)', 'https://www.news24.com/Africa/News/female-ban-during-nigerian-festival-causes-uproar-20180510', 'How can old traditions and modern city life make room for each other?', 'Ikorodu', 3.504127, 6.619123, 'area', 'medium', 'osm:relation/3718194', null, 500, null, false, '/cards/s1/front/IKD-IKO-11.webp', '/cards/s1/back/IKD-IKO-11.webp', '/cards/s1/thumb/IKD-IKO-11.webp', null),
('IKD-IKO-12', 'ikorodu', 'Ikorodu', 'Odun-Osu Festival', 'culture', 'common', 'OSU', 'mask', 'Opens the festival season like a royal starting gun', 'Odun-Osu opens the festival season. Everybody else, please wait your turn.', 'Odun-Osu is the first traditional festival of Ikorodu''s year and opens the season of other celebrations. It is a royal festival led by the Ayangburen.', 'Odun-Osu Festival (Wikipedia)', 'https://en.wikipedia.org/wiki/Odun-Osu_Festival', 'What is the first big celebration of the year in your family?', 'Ikorodu', 3.504127, 6.619123, 'area', 'medium', 'osm:relation/3718194', null, 500, null, false, '/cards/s1/front/IKD-IKO-12.webp', '/cards/s1/back/IKD-IKO-12.webp', '/cards/s1/thumb/IKD-IKO-12.webp', null),
('IKD-IKO-13', 'ikorodu', 'Ikorodu', 'Farm to Lagos', 'food', 'common', 'FARM', 'farm', 'Fills Lagos pots before breakfast', 'Before the food reaches your Lagos pot, Ikorodu don already gather am.', 'Britannica describes Ikorodu as a collecting point for locally produced fish, poultry, cassava, corn, vegetables and palm oil, which are shipped on to Lagos.', 'Ikorodu (Encyclopaedia Britannica)', 'https://www.britannica.com/place/Ikorodu', 'What is the best thing you have ever bought straight from a farm?', 'Ikorodu', 3.504127, 6.619123, 'area', 'medium', 'osm:relation/3718194', null, 500, null, false, '/cards/s1/front/IKD-IKO-13.webp', '/cards/s1/back/IKD-IKO-13.webp', '/cards/s1/thumb/IKD-IKO-13.webp', null),
('IKD-IKO-14', 'ikorodu', 'Ikorodu', 'LASUSTECH', 'institution', 'rare', 'TECH', 'campus', 'Upgrades itself every few decades without stress', 'College to poly to university. That is a glow up with certificates.', 'Lagos State University of Science and Technology began in 1977 as the Lagos State College of Science and Technology, became LASPOTECH in 1986 and turned university under a law signed in 2022.', 'History (Lagos State University of Science and Technology)', 'https://lasustech.edu.ng/history.html', 'Poly or university: which one has the better campus stories?', 'Ikorodu', 3.524484, 6.640207, 'place', 'medium', 'osm:way/746264215', null, 150, 1000, false, '/cards/s1/front/IKD-IKO-14.webp', '/cards/s1/back/IKD-IKO-14.webp', '/cards/s1/thumb/IKD-IKO-14.webp', null),
('IKD-IKO-17', 'ikorodu', 'Ikorodu', 'Ikorodu City FC', 'institution', 'common', 'FC', 'stadium', 'Scores the big goal exactly when it matters', 'From the lower league to the top flight. Ikorodu don land for NPFL.', 'Ikorodu City FC won promotion to the Nigeria Premier Football League in June 2024, sealing it with a 2-0 win over Madiba FC in the NNL Super 8 playoffs in Enugu.', 'Ikorodu City, Beyond Limits FC gain promotion to NPFL (TheCable)', 'https://thecable.ng/ikorodu-city-beyond-limits-fc-gain-promotion-to-npfl', 'Would you rather support your local club or a big European side?', 'Ikorodu', 3.504127, 6.619123, 'area', 'low', 'osm:relation/3718194', 'place not found, centre of its area', 500, null, false, '/cards/s1/front/IKD-IKO-17.webp', '/cards/s1/back/IKD-IKO-17.webp', '/cards/s1/thumb/IKD-IKO-17.webp', null),
('IKD-IMO-01', 'imota', 'Ikorodu', 'The Ranodu of Imota', 'history', 'rare', 'RANODU', 'crown', 'Starts a whole kingdom from one bold move', 'Imota said make we build our own, and they actually did it.', 'Imota''s Oba carries the title Ranodu. Tradition says the first Ranodu, a son of the Awujale Obaruwa, led his people out of Ijebu-Ode to found a separate kingdom.', 'Imota (Wikipedia)', 'https://en.wikipedia.org/wiki/Imota', 'If you founded your own town, what title would your ruler carry?', 'Imota', 3.669449, 6.663619, 'area', 'high', 'osm:node/501463850', null, 500, 1000, false, '/cards/s1/front/IKD-IMO-01.webp', '/cards/s1/back/IKD-IMO-01.webp', '/cards/s1/thumb/IKD-IMO-01.webp', null),
('IKD-IMO-02', 'imota', 'Ikorodu', 'Near the Ota Tree', 'lore', 'common', 'OTA', 'tree', 'Puts a whole town on the map with one tree', 'Some towns take their name from kings. Imota took its own from a tree.', 'Imota''s name is traced to ''Imu-Ota'', meaning ''near the Ota tree'', after the spot where Ranodu''s migrating party settled.', 'Imota (Wikipedia)', 'https://en.wikipedia.org/wiki/Imota', 'What landmark would your street be named after?', 'Imota', 3.669449, 6.663619, 'area', 'high', 'osm:node/501463850', null, 500, null, false, '/cards/s1/front/IKD-IMO-02.webp', '/cards/s1/back/IKD-IMO-02.webp', '/cards/s1/thumb/IKD-IMO-02.webp', null),
('IKD-IMO-03', 'imota', 'Ikorodu', 'The Ota Wood Rule', 'lore', 'common', 'TABOO', 'tree', 'Protects a tree with the power of tradition', 'That tree na family, so e no dey enter the firewood pile.', 'Imota tradition holds that residents must not make fire with wood from the Ota tree, the tree linked to the town''s name.', 'Imota (Wikipedia)', 'https://en.wikipedia.org/wiki/Imota', 'What family tradition do you keep even if nobody explained why?', 'Imota', 3.669449, 6.663619, 'area', 'high', 'osm:node/501463850', null, 500, null, false, '/cards/s1/front/IKD-IMO-03.webp', '/cards/s1/back/IKD-IMO-03.webp', '/cards/s1/thumb/IKD-IMO-03.webp', null),
('IKD-IMO-04', 'imota', 'Ikorodu', 'Agbala Imota', 'history', 'common', 'IDADO', 'town', 'Leaves its name behind wherever it rests', 'Imota left a forwarding address near Sagamu and people still use am.', 'Leaving Ijebu-Ode, Ranodu''s party paused at Idado near Sagamu, where he paid homage to the Akarigbo. Tradition says Idado is still known today as Agbala Imota.', 'Imota (Wikipedia)', 'https://en.wikipedia.org/wiki/Imota', 'Which place carries a trace of your family''s journey?', 'Imota', 3.669449, 6.663619, 'area', 'high', 'osm:node/501463850', null, 500, null, false, '/cards/s1/front/IKD-IMO-04.webp', '/cards/s1/back/IKD-IMO-04.webp', '/cards/s1/thumb/IKD-IMO-04.webp', null),
('IKD-IMO-05', 'imota', 'Ikorodu', 'Imota''s Four Quarters', 'place', 'common', '4', 'town', 'Splits into four and still stays one', 'Four quarters, one town. Pick your side for the street football.', 'Imota town is divided into four quarters: Itun-Opopo, Itun-Onabu, Itun-Maja and Atere.', 'Imota (Wikipedia)', 'https://en.wikipedia.org/wiki/Imota', 'If your area had quarters, what would you name yours?', 'Imota', 3.669449, 6.663619, 'area', 'high', 'osm:node/501463850', null, 500, null, false, '/cards/s1/front/IKD-IMO-05.webp', '/cards/s1/back/IKD-IMO-05.webp', '/cards/s1/thumb/IKD-IMO-05.webp', null),
('IKD-IMO-08', 'imota', 'Ikorodu', 'Eko Rice', 'food', 'common', 'EKO', 'grain', 'Puts a Lagos label on your Sunday rice', 'Eko Rice don land from Imota straight to your pot.', 'Rice from the Imota rice mill is sold under the Eko Rice trademark, Lagos State''s own rice brand.', 'Lagos to commence sale of Eko Rice this week (BusinessDay)', 'https://businessday.ng/news/article/lagos-to-commence-sale-of-eko-rice-this-week/', 'Local rice or foreign rice: which one wins in your house?', 'Imota', 3.669449, 6.663619, 'area', 'low', 'osm:node/501463850', 'place not found, centre of its area', 500, null, false, '/cards/s1/front/IKD-IMO-08.webp', '/cards/s1/back/IKD-IMO-08.webp', '/cards/s1/thumb/IKD-IMO-08.webp', null),
('IKD-IMO-09', 'imota', 'Ikorodu', 'Caleb University', 'institution', 'rare', 'CALEB', 'campus', 'Turns Imota into a student town every semester', 'From take-off site to 110 hectares in Imota. Big campus energy.', 'Caleb University got its provisional licence in May 2007, began classes in January 2008 and moved to its 110-hectare permanent campus at Imota in November 2009.', 'About Caleb University', 'https://website.caleb.university/about', 'What course would you study if you went back to school tomorrow?', 'Imota', 3.636401, 6.669789, 'place', 'high', 'osm:way/747460531', null, 150, 1000, false, '/cards/s1/front/IKD-IMO-09.webp', '/cards/s1/back/IKD-IMO-09.webp', '/cards/s1/thumb/IKD-IMO-09.webp', null),
('IKD-NTH-01', 'ikorodu-north', 'Ikorodu', 'Ikorodu North LCDA', 'place', 'common', 'NORTH', 'town', 'Holds down the northern end of the Ikorodu story', 'Ikorodu got so big it needed six councils. North said, ''I go take this side.''', 'Ikorodu North is one of six councils formed when the old Ikorodu Local Government was split in 2003, alongside Ikorodu, Ikorodu West, Ijede, Imota and Igbogbo-Bayeku.', 'Ikorodu (Wikipedia)', 'https://en.wikipedia.org/wiki/Ikorodu', 'Do you know which council area your street falls under?', 'Ikorodu North', 3.52051, 6.658392, 'area', 'low', 'osm:way/778616167', 'Ikorodu North not found, Odogunyan stands in', 500, null, false, '/cards/s1/front/IKD-NTH-01.webp', '/cards/s1/back/IKD-NTH-01.webp', '/cards/s1/thumb/IKD-NTH-01.webp', null),
('IKD-NTH-02', 'ikorodu-north', 'Ikorodu', 'Isiu and the Eweye', 'place', 'common', 'ISIU', 'town', 'Keeps its own crown inside a crowded kingdom', 'Different town, different crown. Isiu answers to the Eweye.', 'Isiu is a town in Ikorodu North LCDA, and its traditional ruler carries the title Eweye of Isiu.', 'NSCDC Lagos Command groundbreaking in Imota, Isiu (The Mirror)', 'https://themirroronline.com.ng/nscdc-lagos-command-performs-new-sets-of-groundbreaking-in-imota-isiu/', 'How many traditional titles from around Lagos can you name?', 'Ikorodu North', 3.61872, 6.659608, 'area', 'high', 'osm:node/501521905', null, 500, null, false, '/cards/s1/front/IKD-NTH-02.webp', '/cards/s1/back/IKD-NTH-02.webp', '/cards/s1/thumb/IKD-NTH-02.webp', null),
('IKD-NTH-03', 'ikorodu-north', 'Ikorodu', 'Odogunyan', 'place', 'common', 'ODOG', 'factory', 'Runs on factory shifts and big dreams', 'Odogunyan means business. Ask the factories.', 'Ikorodu-born economist Temitope Oshikoya described the Odogunyan area of Ikorodu as one of the largest industrial estates in Nigeria.', 'Ikorodu Economy Summit report (Proshare)', 'https://proshare.co/articles/legacy/news/38606', 'What product would you love to see made in Ikorodu?', 'Ikorodu North', 3.52051, 6.658392, 'area', 'medium', 'osm:way/778616167', null, 500, null, false, '/cards/s1/front/IKD-NTH-03.webp', '/cards/s1/back/IKD-NTH-03.webp', '/cards/s1/thumb/IKD-NTH-03.webp', null),
('IKD-NTH-04', 'ikorodu-north', 'Ikorodu', 'Ebuwawa Market', 'place', 'common', 'MARKET', 'market', 'Keeps the market fresh, from tomatoes to taps', 'Clean water for the market. Wash your hands, then price your tomatoes.', 'Traders at Ebuwawa Market in Ikorodu North LCDA received solar-powered water and sanitation facilities under a WaterAid Nigeria project funded by the PepsiCo Foundation.', 'WaterAid hands over solar-powered WASH facilities in Ikorodu North LCDA (Radio Nigeria Lagos)', 'https://radionigerialagos.gov.ng/?p=33192', 'What is one thing every Lagos market should have?', 'Ikorodu North', 3.52051, 6.658392, 'area', 'low', 'osm:way/778616167', 'place and Ebuwawa not found, Odogunyan stands in', 500, null, false, '/cards/s1/front/IKD-NTH-04.webp', '/cards/s1/back/IKD-NTH-04.webp', '/cards/s1/thumb/IKD-NTH-04.webp', null),
('IKD-NTH-05', 'ikorodu-north', 'Ikorodu', 'Omigo Solar Borehole', 'place', 'common', 'SOLAR', 'tap', 'Turns sunshine into tap water', 'Sun comes up, water comes out. Omigo is running on solar.', 'Omigo, a community in Ikorodu North LCDA, received a 20,000-litre solar-powered borehole from WaterAid Nigeria, expected to supply clean water to about 1,200 residents.', 'Omigo Community Gets 20,000-Litre Solar-Powered Water Facility (Radio Nigeria Lagos)', 'https://radionigerialagos.gov.ng/?p=41966', 'If your street got one new facility tomorrow, what should it be?', 'Ikorodu North', 3.52051, 6.658392, 'area', 'low', 'osm:way/778616167', 'Omigo not found, Odogunyan stands in', 500, null, false, '/cards/s1/front/IKD-NTH-05.webp', '/cards/s1/back/IKD-NTH-05.webp', '/cards/s1/thumb/IKD-NTH-05.webp', null),
('IKD-WST-01', 'ikorodu-west', 'Ikorodu', 'Ikorodu West LCDA', 'place', 'common', 'WEST', 'town', 'Ties many communities together with one council stamp', 'Seven communities, one council, plenty of ''which bus stop you dey?''', 'Ikorodu West LCDA is made up of communities including Owutu, Asolo, Isawo, Ojokoro, Agbede, Ori-Okuta and Igbo-Olomu.', 'Ikorodu residents bemoan flood in community (ICIR)', 'https://www.icirnigeria.org/residents-of-ikorodu-bemoan-the-aftermath-of-flood-due-to-heavy%E2%80%A8downpours/', 'Which of these Ikorodu West communities have you been to?', 'Ikorodu West', 3.479941, 6.619165, 'area', 'low', 'osm:way/778004265', 'Ikorodu West not found, Owutu stands in', 500, null, false, '/cards/s1/front/IKD-WST-01.webp', '/cards/s1/back/IKD-WST-01.webp', '/cards/s1/thumb/IKD-WST-01.webp', null),
('IKD-WST-02', 'ikorodu-west', 'Ikorodu', 'Owutu', 'place', 'common', 'OWUTU', 'town', 'Always one short walk from the bus stop', 'Drop at Agric, waka small, you don reach Owutu.', 'Owutu sits beside Ikorodu''s Agric bus stop and is home to a number of the communities that make up Ikorodu West.', 'Ikorodu residents bemoan flood in community (ICIR)', 'https://www.icirnigeria.org/residents-of-ikorodu-bemoan-the-aftermath-of-flood-due-to-heavy%E2%80%A8downpours/', 'Which Lagos bus stop name confuses visitors the most?', 'Ikorodu West', 3.479941, 6.619165, 'area', 'medium', 'osm:way/778004265', null, 500, null, false, '/cards/s1/front/IKD-WST-02.webp', '/cards/s1/back/IKD-WST-02.webp', '/cards/s1/thumb/IKD-WST-02.webp', null),
('IKD-WST-03', 'ikorodu-west', 'Ikorodu', 'Isawo and the Oke-Afa', 'place', 'common', 'ISAWO', 'town', 'Crosses rivers like they are just another bus stop', 'When the Oke-Afa rises, Isawo people know: plan your route early.', 'Isawo, in Ikorodu West, lies on the Agric-Isawo Road, where the Oke-Afa River overflows in the rainy season. Residents have long pushed for the Afa bridge and the road to be completed.', 'Ikorodu residents beg Sanwo-Olu to fix bad roads (Peoples Gazette)', 'https://gazettengr.com/ikorodu-residents-beg-sanwo-olu-to-fix-bad-roads/', 'What is the most important bridge on your daily journey?', 'Ikorodu West', 3.482366, 6.635244, 'area', 'medium', 'osm:way/1434016884', null, 500, null, false, '/cards/s1/front/IKD-WST-03.webp', '/cards/s1/back/IKD-WST-03.webp', '/cards/s1/thumb/IKD-WST-03.webp', null),
('IKD-WST-04', 'ikorodu-west', 'Ikorodu', 'Konu', 'place', 'common', 'KONU', 'town', 'Plots shortcuts across state lines', 'Konu already drew the shortcut. Lagos-Ibadan traffic, take note.', 'Konu residents in Ikorodu West have called for a bridge linking Konu to Ibafo in Ogun State, as a relief route away from the congested Lagos-Ibadan Expressway.', 'Residents seek bridge to link Ishawo, Ibafo (The Guardian Nigeria)', 'https://guardian.ng/?p=113519', 'If you could build one shortcut anywhere in Lagos, where would it go?', 'Ikorodu West', 3.479941, 6.619165, 'area', 'low', 'osm:way/778004265', 'Konu not found, Owutu stands in', 500, null, false, '/cards/s1/front/IKD-WST-04.webp', '/cards/s1/back/IKD-WST-04.webp', '/cards/s1/thumb/IKD-WST-04.webp', null),
('IKD-WST-05', 'ikorodu-west', 'Ikorodu', 'Igbolomu New Yam', 'culture', 'common', 'YAM', 'farm', 'Brings South East harvest vibes to the Ikorodu side', 'Yam don land for Igbolomu. Thanksgiving with Ogene is non-negotiable.', 'Igbo residents of Igbolomu, Ikorodu, celebrate the New Yam Festival through the Igboamaka Progressives Association, with families giving thanks for the harvest and an Ogene dance.', 'Igboamaka Progressives Association celebrates New Yam Festival in Lagos (Primetime Reporters)', 'https://primetimereporters.com/2021/11/igboamaka-progressives-association-celebrates-new-yam-festival-in-lagos', 'Which festival from another part of Nigeria have you celebrated in Lagos?', 'Ikorodu West', 3.479941, 6.619165, 'area', 'low', 'osm:way/778004265', 'Igbolomu not found, Owutu stands in', 500, null, false, '/cards/s1/front/IKD-WST-05.webp', '/cards/s1/back/IKD-WST-05.webp', '/cards/s1/thumb/IKD-WST-05.webp', null),
('IKJ-OJD-02', 'ojodu', 'Ikeja', 'Aro Meta', 'culture', 'rare', 'AROMETA', 'signpost', 'Gives every newcomer the Lagos once over', 'The three elders dey watch every Johnny Just Come wey enter.', 'Aro Meta, the statue of three Lagos white-cap chiefs over 12 ft tall, was made by sculptor Bodun Shodeinde in 1991 and first stood opposite Ojodu-Berger bus stop to welcome people entering Lagos.', 'Welcome to Lagos (statue) (Wikipedia)', 'https://en.wikipedia.org/wiki/Welcome_to_Lagos_(statue)', 'What advice would you give someone arriving in Lagos for the first time?', 'Ojodu', 3.368509, 6.641564, 'area', 'low', 'osm:node/14161645999', 'place not found, centre of its area', 500, 1000, false, '/cards/s1/front/IKJ-OJD-02.webp', '/cards/s1/back/IKJ-OJD-02.webp', '/cards/s1/thumb/IKJ-OJD-02.webp', null),
('IKJ-ONI-01', 'onigbongbo', 'Ikeja', 'Kalakuta Museum', 'music', 'rare', 'FELA', 'drum', 'Plays Afrobeat even when the speakers are off', 'Na here Abami Eda rest im head. The music never sleep.', 'Fela''s three-storey home at 7 Gbemisola Street, off Allen Avenue, opened as the Kalakuta Republic Museum on 15 October 2012, his 74th birthday. It shows his clothes, instruments and artwork.', 'Kalakuta Republic (Wikipedia)', 'https://en.wikipedia.org/wiki/Kalakuta_Republic', 'Which Fela song would you play to welcome a visitor to Lagos?', 'Onigbongbo', 3.347797, 6.602869, 'place', 'medium', 'osm:way/136415237', null, 150, 1000, false, '/cards/s1/front/IKJ-ONI-01.webp', '/cards/s1/back/IKJ-ONI-01.webp', '/cards/s1/thumb/IKJ-ONI-01.webp', null),
('KSF-AGB-01', 'agboyi-ketu', 'Ikeja', 'Agboyi Creek Escape', 'history', 'common', '1845', 'water', 'Hides a fleeing king in plain water', 'Even war captain fit show mercy for Agboyi water.', 'In 1845, after Kosoko''s forces besieged his palace in the Salt Water War, Oba Akitoye fled north across the lagoon. Kosoko''s war captain Oshodi Tapa granted him safe passage through the Agboyi Creek.', 'Akitoye (Wikipedia)', 'https://en.wikipedia.org/wiki/Akitoye', 'Who showed you mercy when they didn''t have to?', 'Agboyi-Ketu', 3.405797, 6.577984, 'area', 'high', 'osm:node/14161693339', null, 500, null, false, '/cards/s1/front/KSF-AGB-01.webp', '/cards/s1/back/KSF-AGB-01.webp', '/cards/s1/thumb/KSF-AGB-01.webp', null),
('KSF-AGB-02', 'agboyi-ketu', 'Ikeja', 'Agboyi Villages', 'culture', 'common', 'AGBOYI', 'town', 'Keeps six villages under one crown', 'Six villages, one Oba, and the river dey watch everything.', 'Local history says Agboyi was founded by Odoyi, who left the old Awori town of Isheri. Today it is a riverside community of six villages, with its Oba seated at Agboyi 1.', 'Pains of Neglect in Agboyi Community (ThisDay)', 'https://thisdaylive.com/index.php/2016/11/09/pains-of-neglect-in-agboyi-community', 'Which Lagos waterside community have you visited?', 'Agboyi-Ketu', 3.405797, 6.577984, 'area', 'high', 'osm:node/14161693339', null, 500, null, false, '/cards/s1/front/KSF-AGB-02.webp', '/cards/s1/back/KSF-AGB-02.webp', '/cards/s1/thumb/KSF-AGB-02.webp', null),
('KSF-IKO-01', 'ikosi-isheri', 'Ikeja', 'Kosi Kosi', 'history', 'common', 'KOSI', 'signpost', 'Never hides a thing from a guest', 'For Ikosi, nothing dey hide from visitor. Kosi kosi!', 'Local history says Ikosi was founded in the 17th century by Aina Ejo, son of Ile-Ife prince Akanbiogun. Folklore says the name is short for ''Kosi Kosi'', the settlers'' promise to visitors that nothing was hoarded.', 'Ikosi (Wikipedia)', 'https://en.wikipedia.org/wiki/Ikosi', 'What does the name of your area mean?', 'Ikosi-Isheri', 3.383611, 6.600556, 'area', 'high', 'osm:node/501463132', null, 500, null, false, '/cards/s1/front/KSF-IKO-01.webp', '/cards/s1/back/KSF-IKO-01.webp', '/cards/s1/thumb/KSF-IKO-01.webp', null),
('LIS-EAS-01', 'lagos-island-east', 'Lagos', 'Epetedo', 'history', 'common', '1862', 'town', 'Remembers every compound by name', 'Na here Kosoko people settle when dem come back home.', 'Epetedo was founded on 16 September 1862 by followers of Oba Kosoko, led by Chief Oshodi Tapa, after about a decade away. Local history says the name points to early settlers from Epe.', 'Lagos Islanders, Epetedo residents celebrate 155 years of existence (The Guardian Nigeria)', 'https://guardian.ng/news/lagos-islanders-epetedo-residents-celebrate-155-years-of-existence/', 'Which Lagos Island street do you think has the best stories?', 'Lagos Island East', 3.39418, 6.455058, 'area', 'low', 'osm:node/27565124', 'Epetedo not found, Lagos Island stands in', 500, null, false, '/cards/s1/front/LIS-EAS-01.webp', '/cards/s1/back/LIS-EAS-01.webp', '/cards/s1/thumb/LIS-EAS-01.webp', null),
('LIS-EAS-02', 'lagos-island-east', 'Lagos', 'The Epetedo Declaration', 'history', 'rare', '1994', 'scroll', 'Speaks louder than any annulment', 'Na here June 12 talk loud pass.', 'On 11 June 1994, MKO Abiola declared himself president-elect at the Eleganza Sport Centre in Epetedo, a year after the 12 June 1993 election was annulled. The speech led to his arrest.', 'Epetedo community relives Abiola''s historic declaration 24 years after (The Guardian Nigeria)', 'https://guardian.ng/news/epetedo-community-relives-abiolas-historic-declaration-24-years-after/', 'What does June 12 mean to you?', 'Lagos Island East', 3.39418, 6.455058, 'area', 'low', 'osm:node/27565124', 'place and Epetedo not found, Lagos Island stands in', 500, 1000, false, '/cards/s1/front/LIS-EAS-02.webp', '/cards/s1/back/LIS-EAS-02.webp', '/cards/s1/thumb/LIS-EAS-02.webp', null),
('MSH-01', 'mushin', 'Ikeja', 'LUTH Idi-Araba', 'institution', 'rare', 'LUTH', 'hospital', 'Trains doctors and heals the mainland at the same time', 'Idi-Araba wards don see Lagos through every kind of night.', 'Lagos University Teaching Hospital opened in 1962 at Idi-Araba, on a 92-acre site once occupied by the Mainland Hospital. It grew from a 1961 federal plan to build a full medical school in Lagos.', 'History (Lagos University Teaching Hospital)', 'https://luth.gov.ng/about-us/history', 'Who is the doctor or nurse your family always calls first?', 'Mushin', 3.35655, 6.518272, 'place', 'high', 'osm:way/707848334', null, 150, 1000, false, '/cards/s1/front/MSH-01.webp', '/cards/s1/back/MSH-01.webp', '/cards/s1/thumb/MSH-01.webp', null),
('MSH-03', 'mushin', 'Ikeja', 'Mushin Name', 'history', 'common', 'ISHIN', 'signpost', 'Hides a whole fruit inside one name', 'Before all the hustle, na fruit picking give Mushin im name.', 'Local history says the name Mushin comes from ''mu ishin'', Yoruba for picking the ishin fruit. The area later grew into one of the busiest suburbs on the Lagos mainland.', 'Ojuwoye, Mushin (Wikipedia)', 'https://en.wikipedia.org/wiki/Ojuwoye,_Mushin', 'Which Lagos place name do you think has the best story?', 'Mushin', 3.35087, 6.527584, 'area', 'high', 'osm:node/13439326189', null, 500, null, false, '/cards/s1/front/MSH-03.webp', '/cards/s1/back/MSH-03.webp', '/cards/s1/thumb/MSH-03.webp', null),
('MSH-ODI-01', 'odi-olowo-ojuwoye', 'Ikeja', 'Ojuwoye Market', 'food', 'common', 'OJA', 'market', 'Stretches small money into a full bag', 'Ojuwoye price go make you buy wetin you no plan.', 'Ojuwoye Market in Mushin Olosha is known for its wide range of affordable goods. It is counted among notable Lagos markets alongside Oshodi and Tejuosho.', 'Mushin Olosha (Wikipedia)', 'https://en.wikipedia.org/wiki/Mushin_Olosha', 'What''s the cheapest good thing you ever bought at a market?', 'Odi-Olowo/Ojuwoye', 3.35, 6.533333, 'area', 'low', 'wikipedia:Ojuwoye,_Mushin', 'place not found, centre of its area', 500, null, false, '/cards/s1/front/MSH-ODI-01.webp', '/cards/s1/back/MSH-ODI-01.webp', '/cards/s1/thumb/MSH-ODI-01.webp', null),
('MSH-ODI-02', 'odi-olowo-ojuwoye', 'Ikeja', 'Ojuwoye Town', 'place', 'common', 'OJUWOYE', 'town', 'Keeps Mushin''s centre beating', 'Mushin get many corners, but Ojuwoye na the heartbeat.', 'Ojuwoye Town is described as the centre of Mushin, the crowded mainland suburb about 10 km north of Lagos city centre beside the main road to Ikeja.', 'Ojuwoye, Mushin (Wikipedia)', 'https://en.wikipedia.org/wiki/Ojuwoye,_Mushin', 'Where is the true centre of your neighbourhood?', 'Odi-Olowo/Ojuwoye', 3.35, 6.533333, 'area', 'medium', 'wikipedia:Ojuwoye,_Mushin', null, 500, null, false, '/cards/s1/front/MSH-ODI-02.webp', '/cards/s1/back/MSH-ODI-02.webp', '/cards/s1/thumb/MSH-ODI-02.webp', null),
('MUS-45', 'music', 'City-wide', 'Isale Eko Were Roots', 'music', 'common', 'WERE', 'drum', 'Were and ajiwere, the roots of fuji', 'Na Ramadan wake up call wey turn to the whole owambe sound.', 'Fuji grew out of were, also called ajisari, music performed to wake Muslims before dawn in Ramadan. In the early independence years, Isale Eko on Lagos Island had a notable line up of ajiwere performers, before Sikiru Ayinde Barrister turned were into fuji.', 'Were music (Wikipedia)', 'https://en.wikipedia.org/wiki/Were_music', 'Have you ever been woken up by music in the early morning in Lagos?', 'Lagos Island', 3.39418, 6.455058, 'citywide', 'high', 'osm:node/27565124', 'Lagos Island anchor, not a stampable spot', null, null, false, '/cards/s1/front/MUS-45.webp', '/cards/s1/back/MUS-45.webp', '/cards/s1/thumb/MUS-45.webp', null),
('MUS-47', 'music', 'City-wide', 'The Headies', 'music', 'common', 'HEADIES', 'seal', 'Nigeria''s leading music awards', 'The night every Naija artist dey pray to carry that head.', 'The Headies began in 2006 as the Hip Hop World Awards and took its current name in 2011. Its first two editions were held at the Muson Centre in Onikan, Lagos, and the 2010 to 2012 editions at Eko Hotel, Victoria Island.', 'The Headies (Wikipedia)', 'https://en.wikipedia.org/wiki/The_Headies', 'Who would you hand a Headies award to tonight?', 'Lagos Island', 3.39418, 6.455058, 'citywide', 'high', 'osm:node/27565124', 'Lagos Island anchor, not a stampable spot', null, null, false, '/cards/s1/front/MUS-47.webp', '/cards/s1/back/MUS-47.webp', '/cards/s1/thumb/MUS-47.webp', null),
('OJO-IBA-02', 'iba', 'Badagry', 'Obadore First Camp', 'history', 'common', 'OBADORE', 'seal', 'Where the northern Ojo story starts', 'Before Ojo spread, na Obadore people first rest their load.', 'Local history says later Awori migrants from Ile-Ife first settled at Obadore in Iba, then spread west and southwest. Iba and Igbo-Elerin grew as Ojo''s northern section, separate from the western Oto-Awori side.', 'Ojo, Lagos (Wikipedia)', 'https://en.wikipedia.org/wiki/Ojo,_Lagos', 'Which part of your area do the elders say was settled first?', 'Iba', 3.224239, 6.536632, 'area', 'medium', 'osm:way/113526412', null, 500, null, false, '/cards/s1/front/OJO-IBA-02.webp', '/cards/s1/back/OJO-IBA-02.webp', '/cards/s1/thumb/OJO-IBA-02.webp', null),
('OJO-OTO-01', 'oto-awori', 'Badagry', 'Oto, Once Ijake', 'history', 'common', 'IJAKE', 'signpost', 'Remembers the name it had before', 'Before Oto, na Ijake. Ask any Oto elder.', 'Local history recorded in a 1939 colonial report says Oto was founded in the 18th century by Benin migrants led by Aregi Ope. First called Ijake, it took the name Oto after a land division at Igbo-Ogo fixed its boundary with Iba.', 'Oto-Awori (Wikipedia)', 'https://en.wikipedia.org/wiki/Oto-Awori', 'Do you know the old name of the place you grew up?', 'Oto-Awori', 3.1208, 6.496658, 'area', 'low', 'osm:node/501463429', 'Oto not found, Ijanikin stands in', 500, null, false, '/cards/s1/front/OJO-OTO-01.webp', '/cards/s1/back/OJO-OTO-01.webp', '/cards/s1/thumb/OJO-OTO-01.webp', null),
('OJO-OTO-02', 'oto-awori', 'Badagry', 'FGC Ijanikin', 'institution', 'rare', '1975', 'graduate', 'Mixes students from every corner of Nigeria', 'For FGC Ijanikin, Lagos pikin learn to be Nigerian together.', 'Federal Government College Ijanikin was set up by the Federal Ministry of Education in 1975, giving Lagos a co-educational federal unity school like the other 12 states of the time. Its first principal served from October 1975.', 'Federal Government College, Ijanikin (Wikipedia)', 'https://en.wikipedia.org/wiki/Federal_Government_College,_Ijanikin', 'Did you go to a boarding school, and what did you miss most from home?', 'Oto-Awori', 3.135117, 6.490628, 'place', 'high', 'osm:way/741313010', null, 150, 1000, false, '/cards/s1/front/OJO-OTO-02.webp', '/cards/s1/back/OJO-OTO-02.webp', '/cards/s1/thumb/OJO-OTO-02.webp', null),
('OSH-01', 'oshodi-isolo', 'Ikeja', 'Oshodi Tapa', 'history', 'common', 'TAPA', 'staff', 'Turns a war captain into the bus stop everyone shouts', 'Every conductor wey shout ''Oshodi!'' dey call a war captain name.', 'Local history says Oshodi takes its name from Chief Oshodi Tapa, a Nupe-born child raised in the Lagos palace who became war captain to Oba Kosoko and led the 1845 siege known as the Salt Water War.', 'Oshodi Tapa (Wikipedia)', 'https://en.wikipedia.org/wiki/Oshodi_Tapa', 'Which Lagos bus stop name has the wildest backstory you know?', 'Oshodi-Isolo', 3.349442, 6.557025, 'area', 'medium', 'osm:node/13136676804', null, 500, null, false, '/cards/s1/front/OSH-01.webp', '/cards/s1/back/OSH-01.webp', '/cards/s1/thumb/OSH-01.webp', null),
('OSH-EJI-01', 'ejigbo', 'Ikeja', 'Jakande Estate Oke-Afa', 'history', 'common', '1983', 'town', 'Turns renters into homeowners', 'Baba Kekere build am, Oke-Afa people still dey call am home.', 'Jakande Estate at Oke-Afa is one of the low-cost housing estates built under Lateef Jakande, Lagos''s first civilian governor. A 2023 tribute dates its opening to December 1983, days before the military took power.', 'Jakande, Progressivism and Revisionis[m] (ThisDay, opinion)', 'https://www.thisdaylive.com/2023/12/15/jakande-progressivism-and-revisionis/', 'Did anyone in your family live in a Jakande estate?', 'Ejigbo', 3.293436, 6.549451, 'area', 'low', 'osm:node/14161650367', 'place not found, centre of its area', 500, null, false, '/cards/s1/front/OSH-EJI-01.webp', '/cards/s1/back/OSH-EJI-01.webp', '/cards/s1/thumb/OSH-EJI-01.webp', null),
('OSH-EJI-02', 'ejigbo', 'Ikeja', 'Ifoshi Road', 'place', 'common', 'IFOSHI', 'signpost', 'Carries all of Ejigbo to the expressway', 'For Ejigbo, once you reach Ifoshi, you don almost reach house.', 'Ifoshi Road is Ejigbo''s main access route, linking the community to the Oshodi-Apapa Expressway through the Ikotun-Ejigbo junction. After more than two decades in poor shape, it was rebuilt and reopened in September 2024.', 'Ifoshi Road Gets Facelift After 26 Years (ThisDay)', 'https://thisdaylive.com/index.php/2024/09/26/ifoshi-road-gets-facelift-after-26-years', 'Which road takes you home, and what do you see on it?', 'Ejigbo', 3.300626, 6.543828, 'place', 'high', 'osm:way/1436178575', null, 150, null, false, '/cards/s1/front/OSH-EJI-02.webp', '/cards/s1/back/OSH-EJI-02.webp', '/cards/s1/thumb/OSH-EJI-02.webp', null),
('OSH-ISO-02', 'isolo', 'Ikeja', 'Isolo General Hospital', 'institution', 'common', 'ISOLO', 'hospital', 'Patches up Isolo, from first cry to check-up', 'When Isolo body no correct, na here people dey run go.', 'Isolo General Hospital is a Lagos State public hospital serving Isolo and nearby areas with emergency, maternity and outpatient care, plus specialist treatment.', 'Isolo General Hospital (Wikipedia)', 'https://en.wikipedia.org/wiki/Isolo_General_Hospital', 'What''s one thing that would make Lagos hospitals better?', 'Isolo', 3.31892, 6.527288, 'place', 'high', 'osm:way/788305530', null, 150, null, false, '/cards/s1/front/OSH-ISO-02.webp', '/cards/s1/back/OSH-ISO-02.webp', '/cards/s1/thumb/OSH-ISO-02.webp', null),
('SHO-01', 'shomolu', 'Ikeja', 'Shomolu Printing District', 'culture', 'common', 'PRINT', 'press', 'Prints your wedding programme overnight', 'You need 500 flyers by morning? Shomolu no dey sleep.', 'Shomolu is Lagos''s printing capital, with offset and digital print shops packed along Bajulaiye Road and Oguntolu. A 2016 count found about 200 print shops, many in small kiosks attached to homes.', 'Somolu (Wikipedia)', 'https://en.wikipedia.org/wiki/Somolu', 'What''s the last thing you got printed in a rush?', 'Shomolu', 3.384163, 6.533565, 'area', 'medium', 'osm:relation/3718199', null, 500, null, false, '/cards/s1/front/SHO-01.webp', '/cards/s1/back/SHO-01.webp', '/cards/s1/thumb/SHO-01.webp', null),
('SHO-BAR-01', 'bariga', 'Ikeja', 'FCE (Technical) Akoka', 'institution', 'rare', '1967', 'graduate', 'Turns technicians into teachers', 'Na here Lagos technical teachers dey learn how to teach.', 'Founded by the federal government in 1967, this Akoka college trains teachers for technical, vocational and commercial subjects. It started life as the National Technical Teachers College.', 'Federal College of Education (Technical), Akoka (Wikipedia)', 'https://en.wikipedia.org/wiki/Federal_College_of_Education_(Technical),_Akoka', 'Which teacher made a subject finally click for you?', 'Bariga', 3.384738, 6.521532, 'place', 'high', 'osm:way/735021280', null, 150, 1000, false, '/cards/s1/front/SHO-BAR-01.webp', '/cards/s1/back/SHO-BAR-01.webp', '/cards/s1/thumb/SHO-BAR-01.webp', null),
('SHO-BAR-02', 'bariga', 'Ikeja', 'Crown Troupe of Africa', 'culture', 'common', 'BOAT', 'drum', 'Turns any open street into a theatre', 'For Bariga, the street na stage and everybody na audience.', 'Bariga is home base of Crown Troupe of Africa, a total theatre company blending dance, drama, music and Yoruba masquerade style. Its Bariga Open Air Theatre carnival grew into the Eko Theatre Festival.', '2018 Eko Theatre Festival rounds off today (The Guardian Nigeria)', 'https://guardian.ng/art/2018-eko-theatre-festival-rounds-off-today/', 'Have you ever watched a play performed on the street?', 'Bariga', 3.388037, 6.540728, 'area', 'low', 'osm:node/501502941', 'place not found, centre of its area', 500, null, false, '/cards/s1/front/SHO-BAR-02.webp', '/cards/s1/back/SHO-BAR-02.webp', '/cards/s1/thumb/SHO-BAR-02.webp', null),
('SUR-03', 'surulere', 'Lagos', 'Surulere: Patience Pays', 'history', 'common', 'SURU', 'seal', 'Rewards anyone who waits small', 'Na patience build Surulere, na patience go reward you.', 'Surulere roughly means patience and perseverance in Yoruba. Its New Lagos area, also called the Surulere Re-Housing Estate, was among the first public housing projects in Nigeria.', 'Surulere (Wikipedia)', 'https://en.wikipedia.org/wiki/Surulere', 'What is the best thing you ever got because you waited?', 'Surulere', 3.357116, 6.500803, 'area', 'medium', 'osm:node/501527946', null, 500, null, false, '/cards/s1/front/SUR-03.webp', '/cards/s1/back/SUR-03.webp', '/cards/s1/thumb/SUR-03.webp', null),
('SUR-COK-01', 'coker-aguda', 'Lagos', 'Coker: Named for a Family', 'history', 'common', 'COKER', 'signpost', 'Keeps the factories humming', 'Na one family name, now na whole bus stop.', 'Wikipedia says Lagos''s Coker district is named after the Coker family, long led by Justice G. B. A. Coker. Coker, with Iponri and Iganmu, is also where most of Surulere''s industrial firms sit.', 'G. B. A. Coker (Wikipedia)', 'https://en.wikipedia.org/wiki/G._B._A._Coker', 'Which Lagos street or area is named after a family you know?', 'Coker-Aguda', 3.333934, 6.4793, 'area', 'high', 'osm:node/14136561162', null, 500, null, false, '/cards/s1/front/SUR-COK-01.webp', '/cards/s1/back/SUR-COK-01.webp', '/cards/s1/thumb/SUR-COK-01.webp', null),
('SUR-COK-02', 'coker-aguda', 'Lagos', 'Aguda: The Returnees'' Name', 'culture', 'common', 'AGUDA', 'scroll', 'Carries a Brazil story in its name', 'Who dey Aguda today fit get Bahia story for blood.', 'Aguda is the Yoruba name for freed Africans who came back from Brazil, in use in Lagos from about 1835. Surulere''s history records Aguda and Saro returnees from Brazil and Cuba settling in Surulere in the 19th century.', 'Àgùdà (YorubaName.com)', 'https://www.yorubaname.com/entries/Àgùdà?lang=yo', 'Do you know any Lagos family with Brazilian roots?', 'Coker-Aguda', 3.357116, 6.500803, 'area', 'low', 'osm:node/501527946', 'Aguda not found, Surulere stands in', 500, null, false, '/cards/s1/front/SUR-COK-02.webp', '/cards/s1/back/SUR-COK-02.webp', '/cards/s1/thumb/SUR-COK-02.webp', null),
('SUR-ITI-01', 'itire-ikate', 'Lagos', 'Itire and the Onitire', 'history', 'common', 'ITIRE', 'crown', 'Wears its own crown on the Mainland', 'Itire get Kabiyesi, no be small place o.', 'Itire is one of Surulere''s quarters with its own recognised traditional ruler, the Onitire of Itire. A 2023 essay on Lagos institutions lists the Onitire alongside the Oniru of Iruland and the Elegushi of Ikateland.', 'Surulere (Wikipedia)', 'https://en.wikipedia.org/wiki/Surulere', 'Do you know who the traditional ruler of your area is?', 'Itire-Ikate', 3.330049, 6.508136, 'area', 'high', 'osm:node/14136619313', null, 500, null, false, '/cards/s1/front/SUR-ITI-01.webp', '/cards/s1/back/SUR-ITI-01.webp', '/cards/s1/thumb/SUR-ITI-01.webp', null),
('UNI-01', 'unilag-series', 'Campus series', 'Born in 1962', 'institution', 'common', '1962', 'campus', 'Turns a temporary site into a permanent institution', 'Temporary site for Surulere, permanent vibes for Akoka. Na so legends start.', 'UNILAG was established by University of Lagos Act No. 11 of 1962. Lectures began on 22 October 1962 at a temporary site in Surulere, before the move to Akoka.', 'UNILAG Historical Odyssey - University Of Lagos', 'https://unilag.edu.ng/unilag-historical-odyssey/', 'Who in your family was the first to school in UNILAG?', 'UNILAG, Akoka', 3.393531, 6.512027, 'area', 'high', 'osm:way/539288366', null, 500, null, false, '/cards/s1/front/UNI-01.webp', '/cards/s1/back/UNI-01.webp', '/cards/s1/thumb/UNI-01.webp', null),
('UNI-03', 'unilag-series', 'Campus series', 'Akoka Main Campus', 'place', 'common', 'AKOKA', 'campus', 'Lagoon breeze on demand, 802 acres deep', 'Water views without paying Lekki rent. Akoka understood the assignment.', 'UNILAG''s main campus sits on 802 acres of land at Akoka and is largely surrounded by the Lagos Lagoon.', 'University of Lagos (Devex organization profile)', 'https://www.devex.com/organizations/university-of-lagos-52640', 'Which shortcut across the Akoka campus did you swear by?', 'UNILAG, Akoka', 3.393531, 6.512027, 'place', 'high', 'osm:way/539288366', null, 150, null, false, '/cards/s1/front/UNI-03.webp', '/cards/s1/back/UNI-03.webp', '/cards/s1/thumb/UNI-03.webp', null),
('UNI-05', 'unilag-series', 'Campus series', 'In Deed and in Truth', 'lore', 'common', 'No.1', 'seal', 'Wins any school argument in one sentence', 'Say it with your chest: First Choice, Nation''s Pride.', 'UNILAG''s motto is ''In deed and in truth'', and its official slogan is ''University of First Choice and the Nation''s Pride''.', 'UNILAG SERVICOM Service Charter', 'https://unilag.edu.ng/wp-content/uploads/2025/04/SERVICOM_CHARTER_23_07_24.pdf', 'Is UNILAG really the University of First Choice? Defend your answer.', 'UNILAG, Akoka', 3.393531, 6.512027, 'area', 'high', 'osm:way/539288366', null, 500, null, false, '/cards/s1/front/UNI-05.webp', '/cards/s1/back/UNI-05.webp', '/cards/s1/thumb/UNI-05.webp', null),
('UNI-07', 'unilag-series', 'Campus series', 'J.F. Ade Ajayi Auditorium', 'place', 'common', 'AUDI', 'columns', 'Turns any gathering into a big UNILAG moment', 'Call am Main Audi or call am Ade Ajayi. Just no come late.', 'The J.F. Ade Ajayi Auditorium, formerly the Main Auditorium, honours historian Prof. J.F. Ade Ajayi, UNILAG''s third Vice-Chancellor (1972 to 1978).', 'History of Vice Chancellors - University Of Lagos', 'https://unilag.edu.ng/history-of-vice-chancellors/', 'What''s the most memorable event you attended at the Main Auditorium?', 'UNILAG, Akoka', 3.393531, 6.512027, 'area', 'low', 'osm:way/539288366', 'place not found, centre of its area', 500, null, false, '/cards/s1/front/UNI-07.webp', '/cards/s1/back/UNI-07.webp', '/cards/s1/thumb/UNI-07.webp', null),
('UNI-08', 'unilag-series', 'Campus series', 'Hall Roll Call', 'tradition', 'common', 'HALLS', 'people', 'Turns strangers into hall family for life', 'Your hall is your tribe. Choose wisely, defend loudly.', 'Jaja, Moremi, Kofo Ademola, Fagunwa and Madam Tinubu are among UNILAG''s halls of residence. All five reopened to students in June 2025 after renovation works.', 'Important Notice: Update on Movement into Halls of Residence', 'https://unilag.edu.ng/important-notice-update-on-movement-into-halls-of-residence/', 'Which hall did you stay in, and which hall had the best gist?', 'UNILAG, Akoka', 3.393531, 6.512027, 'area', 'high', 'osm:way/539288366', null, 500, null, false, '/cards/s1/front/UNI-08.webp', '/cards/s1/back/UNI-08.webp', '/cards/s1/thumb/UNI-08.webp', null),
('UNI-09', 'unilag-series', 'Campus series', 'UNILAG 103.1 FM', 'institution', 'common', '103.1', 'radio', 'Broadcasts campus gist at the speed of sound', 'Campus gist with a licence. Tune in, no dull.', 'UNILAG got its radio licence in 2002, and UNILAG 103.1 FM began broadcasting live in 2004. The station says it was Nigeria''s first university radio station to go live.', 'About - UNILAG Radio 103.1 FM', 'https://unilagradio1031.com.ng/about-3/', 'Have you ever been on air at UNILAG 103.1 FM, or called in?', 'UNILAG, Akoka', 3.393531, 6.512027, 'area', 'low', 'osm:way/539288366', 'place not found, centre of its area', 500, null, false, '/cards/s1/front/UNI-09.webp', '/cards/s1/back/UNI-09.webp', '/cards/s1/thumb/UNI-09.webp', null),
('YAB-01', 'yaba', 'Lagos Mainland', 'Yaba Higher College', 'institution', 'epic', '1932', 'graduate', 'Ships a whole student body to Ibadan and calls it a university', 'Before Ibadan had a campus, Yaba was already doing the homework.', 'Founded in Yaba in 1932, it trained Africans in fields like medicine, engineering and teaching. In 1948 its students and equipment moved to Ibadan to start University College, Ibadan.', 'Yaba College - Wikipedia', 'https://en.wikipedia.org/wiki/Yaba_College', 'Which school in your family history goes back the furthest?', 'Yaba', 3.374141, 6.518728, 'place', 'high', 'osm:way/671850885', null, 150, 100, true, '/cards/s1/front/YAB-01.webp', '/cards/s1/back/YAB-01.webp', '/cards/s1/thumb/YAB-01.webp', null),
('YAB-03', 'yaba', 'Lagos Mainland', 'Queen''s College', 'institution', 'epic', 'QC', 'graduate', 'Produces trailblazing women by the class-load', 'Pass on the torch, then pass the gist at the reunion.', 'Opened on 10 October 1927 as the Government School for Girls, Lagos, the first government-owned school for girls. It became Queen''s College in 1928 and moved to Yaba in 1958.', 'About Queen''s College (alumni history page)', 'https://www.oocities.org/qcollege/aboutqc.html', 'Who is the most impressive Queen''s College old student you know?', 'Yaba', 3.381581, 6.507678, 'place', 'medium', 'wikipedia:Queen''s_College,_Lagos', null, 150, 100, true, '/cards/s1/front/YAB-03.webp', '/cards/s1/back/YAB-03.webp', '/cards/s1/thumb/YAB-03.webp', null),
('YAB-04', 'yaba', 'Lagos Mainland', 'FSTC Yaba', 'institution', 'rare', 'FSTC', 'graduate', 'Builds engineers before they finish secondary school', 'Science, tech and Yaba hustle, all on one timetable.', 'Founded in 1948, Federal Science and Technical College, Yaba is a mixed secondary school and one of over 100 federal government unity schools run by the Federal Ministry of Education.', 'Federal Science and Technical College, Yaba - Wikipedia', 'https://en.wikipedia.org/wiki/Federal_Science_and_Technical_College,_Yaba', 'If you could master one technical trade overnight, which would it be?', 'Yaba', 3.375488, 6.506821, 'area', 'low', 'osm:node/14136598607', 'place not found, centre of its area', 500, 1000, false, '/cards/s1/front/YAB-04.webp', '/cards/s1/back/YAB-04.webp', '/cards/s1/thumb/YAB-04.webp', null),
('YAB-06', 'yaba', 'Lagos Mainland', 'St Finbarr''s College', 'institution', 'rare', 'SFC', 'graduate', 'Turns schoolboys into Super Eagles', 'Came for the books, left with a first touch.', 'Founded by Irish priest and football administrator Fr Denis Slattery, St Finbarr''s College in Akoka produced Nigerian football stars including the late Stephen Keshi.', 'Flashback: Longest-stayed football expatriate, Fr Slattery dies - Sports Village Square', 'https://sportsvillagesquare.com/2020/07/07/flashback-longest-stayed-football-expatriate-fr-slattery-dies/', 'Which Nigerian footballer would you most want on your five-a-side team?', 'Yaba', 3.391563, 6.534861, 'place', 'medium', 'osm:way/1508800992', null, 150, 1000, false, '/cards/s1/front/YAB-06.webp', '/cards/s1/back/YAB-06.webp', '/cards/s1/thumb/YAB-06.webp', null),
('YAB-07', 'yaba', 'Lagos Mainland', 'Tejuosho Market', 'place', 'common', 'TEJU', 'market', 'Rises from the ashes with extra floors', 'Come for one item, leave with three bags and zero regrets.', 'After fire gutted the old Tejuosho market in 2007, a partnership of Lagos State, Stormberg Engineering and First Bank rebuilt it as a large shopping complex on Ojuelegba-Itire Road.', 'Tejuosho Market - Wikipedia', 'https://en.wikipedia.org/wiki/Tejuosho_Market', 'What is the best bargain you have ever haggled for at a Lagos market?', 'Yaba', 3.369779, 6.508058, 'place', 'high', 'osm:way/671850898', null, 150, null, false, '/cards/s1/front/YAB-07.webp', '/cards/s1/back/YAB-07.webp', '/cards/s1/thumb/YAB-07.webp', null),
('YAB-10', 'yaba', 'Lagos Mainland', 'Yaba Bus Terminal', 'place', 'common', 'BUS', 'terminal', 'Links bus, rail and hustle in one stop', 'The bus finally has a proper home in Yaba.', 'Commissioned by the Lagos State Government on 15 June 2021, the LAMATA-built Yaba Bus Terminal was designed to complement the Lagos Rail Mass Transit Red Line.', 'Lagos Govt Commissions Yaba Bus Terminal - Channels TV', 'https://www.channelstv.com/2021/06/15/lagos-govt-commissions-yaba-bus-terminal', 'What is your most memorable Lagos bus ride story?', 'Yaba', 3.370583, 6.51114, 'place', 'high', 'osm:way/707609369', null, 150, null, false, '/cards/s1/front/YAB-10.webp', '/cards/s1/back/YAB-10.webp', '/cards/s1/thumb/YAB-10.webp', null),
('YAB-11', 'yaba', 'Lagos Mainland', 'Red Line Yaba Station', 'place', 'common', 'RAIL', 'train', 'Beats the go-slow on steel rails', 'Agbado to Yaba with no go-slow? Lagos, is this you?', 'Yaba is one of eight stations on the Lagos Red Line, whose full passenger service started on 15 October 2024 between Agbado and Oyingbo.', 'Red Line Goes Live With Passenger Operation 15th October 2024 - LAMATA', 'https://www.lamata-ng.com/2024/10/14/red-line-goes-live-with-passenger-operation-15th-october-2024-starts-6-00am-from-agbado/', 'Where would you go first if a train could take you anywhere in Lagos?', 'Yaba', 3.369998, 6.511469, 'place', 'high', 'osm:node/12260658329', null, 150, null, false, '/cards/s1/front/YAB-11.webp', '/cards/s1/back/YAB-11.webp', '/cards/s1/thumb/YAB-11.webp', null),
('YAB-12', 'yaba', 'Lagos Mainland', 'CcHub', 'tech', 'rare', 'CcHUB', 'phone', 'Turns a weekend hackathon idea into a real company', 'Every Yaba tech story has a chapter that starts on Herbert Macaulay Way.', 'Co-Creation Hub opened in Yaba in 2011 and became the anchor of its tech cluster. In 2019 it acquired Kenya''s iHub, which Techpoint called the first time an African tech hub bought another.', 'CcHub acquires iHub - Techpoint Africa', 'https://techpoint.africa/news/cchub-acquires-ihub/', 'If you could build one app to fix a Lagos problem, what would it fix?', 'Yaba', 3.37786, 6.504227, 'place', 'high', 'osm:node/3631633695', null, 150, 1000, false, '/cards/s1/front/YAB-12.webp', '/cards/s1/back/YAB-12.webp', '/cards/s1/thumb/YAB-12.webp', null),
('YAB-15', 'yaba', 'Lagos Mainland', 'Yabacon Valley', 'lore', 'common', 'YBA', 'phone', 'Gets called five different names and answers to all of them', 'Silicon Valley who? Yaba has its own valley now.', '''Yabacon Valley'', a blend of Yaba and Silicon Valley, is a popular nickname for Yaba''s tech cluster. It is still debated, with rivals like Silicon Lagoon, Yaba Right and Yaba iHQ.', '#Yabacon: How citizens and innovators have transformed Yaba - YAFRI', 'https://naija.yafri.ca/yabacon-citizens-innovators-transformed-yaba/', 'Yabacon Valley, Silicon Lagoon or just Yaba: what should we call it?', 'Yaba', 3.375488, 6.506821, 'area', 'high', 'osm:node/14136598607', null, 500, null, false, '/cards/s1/front/YAB-15.webp', '/cards/s1/back/YAB-15.webp', '/cards/s1/thumb/YAB-15.webp', null),
('YAB-16', 'yaba', 'Lagos Mainland', 'Yaba Left', 'lore', 'common', '1907', 'signpost', 'Has been caring for Lagos minds for over a century', 'Mental health is health. Respect to everyone working and healing here.', '''Yaba Left'' is Lagos street talk for the Federal Neuro-Psychiatric Hospital, Yaba. It opened in October 1907 as an asylum and is now a federal hospital for mental health care.', 'From asylum to psychiatric hospital: 113-year journey of ''Yaba Left'' - Daily Trust', 'https://dailytrust.com/from-asylum-to-psychiatric-hospital-113-year-journey-of-yaba-left/', 'How can we talk about mental health in Lagos without the jokes?', 'Yaba', 3.373101, 6.510168, 'place', 'high', 'osm:way/803294342', null, 150, null, false, '/cards/s1/front/YAB-16.webp', '/cards/s1/back/YAB-16.webp', '/cards/s1/thumb/YAB-16.webp', null)
) as v(key, set_key, division, name, category, rarity, glyph, motif, known_for, lore, fact, fact_source, fact_url, question, home_area,
       lng, lat, geo_kind, geo_confidence, geo_source, geo_note, radius_m, copies_total, numbered, front_path, back_path, thumb_path, art_credit)
join public.card_sets s on s.key = v.set_key
on conflict (key) do update set
  set_id = excluded.set_id, division = excluded.division, name = excluded.name, category = excluded.category, rarity = excluded.rarity,
  glyph = excluded.glyph, motif = excluded.motif, known_for = excluded.known_for, lore = excluded.lore, fact = excluded.fact,
  fact_source = excluded.fact_source, fact_url = excluded.fact_url, question = excluded.question, home_area = excluded.home_area,
  geog = excluded.geog, geo_kind = excluded.geo_kind, geo_confidence = excluded.geo_confidence, geo_source = excluded.geo_source,
  geo_note = excluded.geo_note, radius_m = excluded.radius_m, copies_total = excluded.copies_total, numbered = excluded.numbered,
  front_path = excluded.front_path, back_path = excluded.back_path, thumb_path = excluded.thumb_path, art_credit = excluded.art_credit;

commit;

select rarity, count(*) as cards, count(*) filter (where status = 'live') as live
from public.cards where season = 1 group by rarity order by public.card_rank(rarity);
